import{_ as a,o,c as t,a2 as r}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"診斷訊息","description":"","frontmatter":{"outline":2},"headers":[],"relativePath":"zh-tw/reference/diagnostics.md","filePath":"zh-tw/reference/diagnostics.md","lastUpdated":1788498435000}'),d={name:"zh-tw/reference/diagnostics.md"};function c(n,e,s,i,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="診斷訊息" tabindex="-1">診斷訊息 <a class="header-anchor" href="#診斷訊息" aria-label="Permalink to &quot;診斷訊息&quot;">​</a></h1><p>本頁列出 emitter 會回報的所有警告與錯誤，附原因與修法。診斷代碼在 compiler 輸出中顯示為 <code>tsp-asyncapi/&lt;code&gt;</code>。</p><h2 id="錯誤" tabindex="-1">錯誤 <a class="header-anchor" href="#錯誤" aria-label="Permalink to &quot;錯誤&quot;">​</a></h2><h3 id="duplicate-schema-key" tabindex="-1"><code>duplicate-schema-key</code> <a class="header-anchor" href="#duplicate-schema-key" aria-label="Permalink to &quot;`duplicate-schema-key`&quot;">​</a></h3><blockquote><p>Duplicate schema name: &#39;&lt;name&gt;&#39;. Check @friendlyName decorators and overlap with types in TypeSpec or service namespace.</p></blockquote><p>兩個宣告解析到同一個 <code>components.schemas</code> key。常見原因：兩個 <code>@friendlyName</code> 解析成同一字串；或 model 名稱撞到 template instantiation 的推導名稱（例如已宣告 <code>model PageString</code>，又使用 <code>Page&lt;string&gt;</code>）。</p><p><strong>修法：</strong> 改掉其中一個宣告的名稱，或給其中一個不同的 <code>@friendlyName</code>。emitter 絕不自動改名。</p><h3 id="payload-schema-key-taken" tabindex="-1"><code>payload-schema-key-taken</code> <a class="header-anchor" href="#payload-schema-key-taken" aria-label="Permalink to &quot;`payload-schema-key-taken`&quot;">​</a></h3><blockquote><p>Schema key &#39;&lt;name&gt;&#39; is claimed twice. Message &#39;&lt;message&gt;&#39; lifts @header fields into its <code>headers</code>, so its payload needs a schema of its own, and that schema is keyed after the message model. Rename the other type that claims &#39;&lt;name&gt;&#39;, or describe the headers of &#39;&lt;message&gt;&#39; with @headers so its payload keeps every field.</p></blockquote><p>會抽出 <code>@header</code> 欄位的 message 不能沿用 model 自己的 schema。那份 schema 仍然描述被抽出的欄位，而那些欄位已經歸入 <code>headers</code>。所以 payload 會另外取得一份 component，key 以 message model 為基底加上 <code>Payload</code> 後綴。現在有另一個宣告先佔走了那把 key。</p><p>payload 的形狀改為就地輸出。若改為引用 model 自己的 component，等於把被抽出的欄位描述成 payload 資料，message 會自相矛盾。</p><p><strong>修法：</strong> 改名另一個型別；或改用 <a href="./decorators/messages#headers"><code>@headers</code></a> 描述 headers，讓 payload 保留所有欄位，就不需要額外的 schema。</p><h3 id="raw-schema-key-taken" tabindex="-1"><code>raw-schema-key-taken</code> <a class="header-anchor" href="#raw-schema-key-taken" aria-label="Permalink to &quot;`raw-schema-key-taken`&quot;">​</a></h3><blockquote><p>Schema key &#39;&lt;name&gt;&#39; is claimed twice. Message &#39;&lt;message&gt;&#39; carries a raw schema that another message carries too, so that schema is written once in <code>components.schemas</code> under a key derived from the message model. Rename the other type that claims &#39;&lt;name&gt;&#39;, or give one of the two messages a different name.</p></blockquote><p>兩個以上的 message 帶著相同的 <a href="./decorators/messages#rawpayload"><code>@rawPayload</code></a> 或 <a href="./decorators/messages#rawheaders"><code>@rawHeaders</code></a>。那份 schema 只寫進 <code>components.schemas</code> 一次，key 以第一個帶著它的 message model 為基底，加上 <code>Payload</code> 或 <code>Headers</code> 後綴。現在有另一個宣告先佔走了那把 key。</p><p>raw schema 改為在每個 message 裡各寫一次。內容沒有遺失，只是文字重複。</p><p><strong>修法：</strong> 改名另一個型別；或替兩個 message 其中之一改名，讓推導出的 key 改變。</p><h3 id="unsupported-payload-type" tabindex="-1"><code>unsupported-payload-type</code> <a class="header-anchor" href="#unsupported-payload-type" aria-label="Permalink to &quot;`unsupported-payload-type`&quot;">​</a></h3><blockquote><p>This emitter does not support a &lt;kind&gt; here. Use a model, scalar, enum, union, or literal value instead.</p></blockquote><p>屬性或 payload 位置指到 schema 層無法轉換的 TypeSpec 實體，例如 <code>Interface</code>、<code>Namespace</code>、<code>Operation</code>。compiler 本身不會拒絕這種寫法，只有 emitter 會。</p><p><strong>修法：</strong> 改用 model、scalar、enum、union 或字面值型別。</p><h3 id="unrepresentable-circular-reference" tabindex="-1"><code>unrepresentable-circular-reference</code> <a class="header-anchor" href="#unrepresentable-circular-reference" aria-label="Permalink to &quot;`unrepresentable-circular-reference`&quot;">​</a></h3><blockquote><p>This anonymous type refers back to itself with no named type in between. A plain (non-$ref) schema cannot express that cycle. Give the type a name so it can be referenced through $ref instead.</p></blockquote><p>匿名型別繞回自己，例如 <code>alias Foo = { a: Foo };</code>。匿名型別只能內嵌（沒有 <code>components.schemas</code> 項目），而內嵌 schema 無法表達循環。</p><p><strong>修法：</strong> 把匿名型別改成具名 <code>model</code>。具名型別之間以 <code>$ref</code> 互相引用，循環沒有問題。</p><h3 id="duplicate-message-key" tabindex="-1"><code>duplicate-message-key</code> <a class="header-anchor" href="#duplicate-message-key" aria-label="Permalink to &quot;`duplicate-message-key`&quot;">​</a></h3><blockquote><p>Duplicate message name: &#39;&lt;name&gt;&#39;. Two @message models resolve to the same components.messages key. Pass an explicit name to @message on one of them.</p></blockquote><p>兩個 <code>@message</code> model 解析到同一個 <code>components.messages</code> key。常見原因：不同 namespace 下的同名 model（message key 不帶 namespace 前綴，schema key 會帶）；或兩個 <code>@friendlyName</code> 解析成同一字串。</p><p>同一個 template 的兩個 instantiation 算出同一個 key 不會回報——原始碼裡只有一個 <code>@message</code>，兩者也指向同一份輸出的 component。</p><p><strong>修法：</strong> 對其中一個的 <code>@message</code> 傳入明確名稱。</p><h3 id="duplicate-message-decorator" tabindex="-1"><code>duplicate-message-decorator</code> <a class="header-anchor" href="#duplicate-message-decorator" aria-label="Permalink to &quot;`duplicate-message-decorator`&quot;">​</a></h3><blockquote><p>@message is applied to this model more than once. Only one application takes effect, and the rest are discarded. Remove the extra @message.</p></blockquote><p><code>@message</code> 不可重複套用。疊加時只會保留其中一次，其餘名稱不會進到文件裡。</p><p><strong>修法：</strong> 移除多餘的 <code>@message</code>。</p><h3 id="duplicate-content-type-decorator" tabindex="-1"><code>duplicate-content-type-decorator</code> <a class="header-anchor" href="#duplicate-content-type-decorator" aria-label="Permalink to &quot;`duplicate-content-type-decorator`&quot;">​</a></h3><blockquote><p>@contentType is applied to this model more than once. A message carries one content type, so only one application takes effect and the rest are discarded. Remove the extra @contentType.</p></blockquote><p><code>@contentType</code> 不可重複套用。一個 message 只有一個 <code>contentType</code> 欄位。疊加時只會保留其中一次，其餘的值會被靜默丟棄。</p><p><strong>修法：</strong> 移除多餘的 <code>@contentType</code>。</p><h3 id="empty-content-type" tabindex="-1"><code>empty-content-type</code> <a class="header-anchor" href="#empty-content-type" aria-label="Permalink to &quot;`empty-content-type`&quot;">​</a></h3><blockquote><p>@contentType was given an empty media type. A blank media type names no format, so it cannot reach the emitted message. This @contentType was dropped, and the message falls back to the document defaultContentType. Give it a media type, such as &#39;application/json&#39;.</p></blockquote><p><a href="./decorators/messages#contenttype"><code>@contentType</code></a> 收到空白的媒體型態。值會先去除前後空白，所以只有空白的值等同空字串。空白的媒體型態沒有指出任何格式，emitter 無法把它寫進 message。</p><p>這個 message 會退回文件層級的 <code>defaultContentType</code>。結果與沒有寫 <code>@contentType</code> 相同。使用者是刻意輸入空字串的，所以這個退回會回報，不會靜默發生。</p><p><strong>修法：</strong> 給這個 decorator 一個媒體型態，例如 <code>application/json</code>，或是移除它。</p><h3 id="duplicate-headers-decorator" tabindex="-1"><code>duplicate-headers-decorator</code> <a class="header-anchor" href="#duplicate-headers-decorator" aria-label="Permalink to &quot;`duplicate-headers-decorator`&quot;">​</a></h3><blockquote><p>@headers is applied to this model more than once. Only one application takes effect, and the rest are discarded. Remove the extra @headers.</p></blockquote><p><code>@headers</code> 不可重複套用。疊加時只會保留其中一次，其餘 headers model 不會進到文件裡。</p><p><strong>修法：</strong> 移除多餘的 <code>@headers</code>。</p><h3 id="duplicate-message-headers" tabindex="-1"><code>duplicate-message-headers</code> <a class="header-anchor" href="#duplicate-message-headers" aria-label="Permalink to &quot;`duplicate-message-headers`&quot;">​</a></h3><blockquote><p>This message takes its headers from more than one source. The three sources are a field marked @header, a model given to @headers, and a schema given to @rawHeaders. There is no rule that picks one over the others, so no <code>headers</code> were emitted at all. Keep one of the sources.</p></blockquote><p>同一個 message 從一個以上的來源宣告 headers。三種來源是標了 <code>@header</code> 的欄位、傳給 <code>@headers</code> 的 model，以及傳給 <code>@rawHeaders</code> 的 schema。emitter 不定義三者的優先序，所以全部都不輸出。被標記的欄位留在 payload，錯誤修好之前不會有任何你寫的東西消失。</p><p><strong>修法：</strong> 只留一個來源。把被標記的欄位搬進 <code>@headers</code> 的 model，或移除 <code>@headers</code> 或 <code>@rawHeaders</code>。</p><h3 id="duplicate-raw-payload-decorator" tabindex="-1"><code>duplicate-raw-payload-decorator</code> <a class="header-anchor" href="#duplicate-raw-payload-decorator" aria-label="Permalink to &quot;`duplicate-raw-payload-decorator`&quot;">​</a></h3><blockquote><p>@rawPayload is applied to this model more than once. A message carries one payload, so only one application takes effect and the rest are discarded. Remove the extra @rawPayload.</p></blockquote><p><code>@rawPayload</code> 不可重複套用。一個 message 只有一個 <code>payload</code> 欄位。疊加時只會保留其中一次，其餘 schema 會被靜默丟棄。</p><p><strong>修法：</strong> 移除多餘的 <code>@rawPayload</code>。</p><h3 id="duplicate-raw-headers-decorator" tabindex="-1"><code>duplicate-raw-headers-decorator</code> <a class="header-anchor" href="#duplicate-raw-headers-decorator" aria-label="Permalink to &quot;`duplicate-raw-headers-decorator`&quot;">​</a></h3><blockquote><p>@rawHeaders is applied to this model more than once. A message carries one headers schema, so only one application takes effect and the rest are discarded. Remove the extra @rawHeaders.</p></blockquote><p><code>@rawHeaders</code> 不可重複套用，理由與 <code>@rawPayload</code> 相同。</p><p><strong>修法：</strong> 移除多餘的 <code>@rawHeaders</code>。</p><h3 id="empty-schema-format" tabindex="-1"><code>empty-schema-format</code> <a class="header-anchor" href="#empty-schema-format" aria-label="Permalink to &quot;`empty-schema-format`&quot;">​</a></h3><blockquote><p>This decorator was given an empty schemaFormat. A blank schemaFormat names no schema language, so it cannot reach the emitted message. This decorator was dropped, and the message falls back to the schema built from the model. Give it a format, such as &#39;application/vnd.apache.avro;version=1.9.0&#39;.</p></blockquote><p><a href="./decorators/messages#rawpayload"><code>@rawPayload</code></a> 或 <a href="./decorators/messages#rawheaders"><code>@rawHeaders</code></a> 收到空字串，或只有空白字元的字串。空白的 <code>schemaFormat</code> 沒有指出任何 schema 語言，emitter 無法把它寫進 message。</p><p>emitter 不會記錄任何東西。該 message 退回使用從 model 建出來的 schema，結果與沒有寫這個 decorator 相同。</p><p><strong>修法：</strong> 給這個 decorator 一個格式，例如 <code>application/vnd.apache.avro;version=1.9.0</code>，或是移除它。</p><h3 id="invalid-raw-schema" tabindex="-1"><code>invalid-raw-schema</code> <a class="header-anchor" href="#invalid-raw-schema" aria-label="Permalink to &quot;`invalid-raw-schema`&quot;">​</a></h3><blockquote><p>The schema given to this decorator cannot be represented as JSON, so it would write nothing into the document. This decorator was dropped, and the message falls back to the schema built from the model. Write the schema as a value the emitter can serialize, such as an object value or a string.</p></blockquote><p>傳給 <a href="./decorators/messages#rawpayload"><code>@rawPayload</code></a> 或 <a href="./decorators/messages#rawheaders"><code>@rawHeaders</code></a> 的 <code>schema</code> 引數，compiler 無法序列化成 JSON。常見原因是自訂 scalar 帶有自己的 <code>init</code> 建構式。</p><p>這個檢查不要求 object，與 <a href="#invalid-binding-config"><code>invalid-binding-config</code></a> 不同。AsyncAPI 把 <code>schema</code> 欄位定義為 <code>any</code>，所以字串與陣列都合法。</p><p><strong>修法：</strong> 把 schema 寫成 emitter 可以序列化的值，例如 object value 或字串。</p><h3 id="non-string-raw-schema" tabindex="-1"><code>non-string-raw-schema</code> <a class="header-anchor" href="#non-string-raw-schema" aria-label="Permalink to &quot;`non-string-raw-schema`&quot;">​</a></h3><blockquote><p>&#39;&lt;format&gt;&#39; is not a JSON based schema language, so AsyncAPI requires its schema to be inlined as a string. This schema was given as an object, and it is emitted as written. Write the schema as a string, such as the text of the .proto definition, or name a format that is JSON based.</p></blockquote><p><a href="./decorators/messages#rawpayload"><code>@rawPayload</code></a> 或 <a href="./decorators/messages#rawheaders"><code>@rawHeaders</code></a> 的 <code>schemaFormat</code> 指的是非 JSON 基礎的 schema 語言，而 <code>schema</code> 引數不是字串。AsyncAPI 規定這種 schema 必須以字串內嵌。規格舉的例子是 Protobuf，表列格式中適用這條規則的就是兩個 Protobuf 識別字。</p><p>schema 仍照原樣輸出，與 <a href="#unknown-schema-format"><code>unknown-schema-format</code></a> 的處理一致。要改哪一邊由你決定。</p><p><strong>修法：</strong> 把 schema 寫成字串，例如 <code>.proto</code> 定義的內容；或改用 JSON 基礎的格式。</p><h3 id="string-raw-schema" tabindex="-1"><code>string-raw-schema</code> <a class="header-anchor" href="#string-raw-schema" aria-label="Permalink to &quot;`string-raw-schema`&quot;">​</a></h3><blockquote><p>&#39;&lt;format&gt;&#39; is a JSON based schema language, so AsyncAPI requires its schema to be inlined rather than given as text to be parsed. This schema is a string that opens a JSON object or array, and the official parser rejects a document that carries one. Write the schema as an object value. Note that a bare JSON string is still allowed, because a format such as Avro names its primitive types that way.</p></blockquote><p><a href="./decorators/messages#rawpayload"><code>@rawPayload</code></a> 或 <a href="./decorators/messages#rawheaders"><code>@rawHeaders</code></a> 的 <code>schemaFormat</code> 指定了以 JSON 為基礎的 schema 語言，而 <code>schema</code> 參數是字串，且第一個非空白字元是物件或陣列的開頭。AsyncAPI 規定這種 schema 直接以值的形式內嵌，不是交出一段文字讓讀取端自行解析。</p><p>不是以物件或陣列開頭的字串不受影響。例如 Avro 就是用 <code>&quot;long&quot;</code> 這種單純字串命名它的原始型別。</p><p>這一條與 <a href="#non-string-raw-schema"><code>non-string-raw-schema</code></a> 互為鏡像，後者處理非 JSON 為基礎的格式卻收到物件的情況。</p><p><strong>修法：</strong> 把 schema 寫成物件值，不要寫成加引號的字串。</p><h3 id="raw-schema-local-ref" tabindex="-1"><code>raw-schema-local-ref</code> <a class="header-anchor" href="#raw-schema-local-ref" aria-label="Permalink to &quot;`raw-schema-local-ref`&quot;">​</a></h3><blockquote><p>This schema refers to &#39;&lt;ref&gt;&#39;, and it is written in &#39;&lt;format&gt;&#39;. AsyncAPI requires both ends of a $ref to carry the same schemaFormat. Every schema this emitter writes into the document is an AsyncAPI Schema Object, so the two ends disagree. The schema is emitted as written. Inline the definition instead of referring to it, or write this schema in the AsyncAPI Schema Object format.</p></blockquote><p>傳給 <a href="./decorators/messages#rawpayload"><code>@rawPayload</code></a> 或 <a href="./decorators/messages#rawheaders"><code>@rawHeaders</code></a> 的 schema，最外層帶有以 <code>#/</code> 開頭的 <code>$ref</code>，而它的 <code>schemaFormat</code> 不是 AsyncAPI Schema Object 格式。這種 reference 指向輸出的文件本身。emitter 寫進該文件的每一個 schema 都是 AsyncAPI Schema Object，所以被指向的一端與指向它的 schema 帶有不同的 <code>schemaFormat</code>。</p><p>emitter 只讀 raw schema 的最外層。巢狀在更深處的 reference 是用該 schema 語言自己寫的，emitter 不讀那個語言。</p><p><strong>修法：</strong> 直接內嵌定義，不要用 reference；或把 schema 改寫成 AsyncAPI Schema Object 格式，例如 <code>application/vnd.aai.asyncapi+json;version=3.1.0</code>。</p><h3 id="unresolved-raw-schema-ref" tabindex="-1"><code>unresolved-raw-schema-ref</code> <a class="header-anchor" href="#unresolved-raw-schema-ref" aria-label="Permalink to &quot;`unresolved-raw-schema-ref`&quot;">​</a></h3><blockquote><p>This schema refers to &#39;&lt;ref&gt;&#39;, and the emitted document holds nothing there. A reference that starts with &#39;#/&#39; points into this document, and the emitter writes every location it can reach. A parser rejects the document as written. Note that a model reaches components.schemas only when some message uses it, and a @rawPayload model is not such a message. Point at a location the document holds, or inline the definition instead of referring to it.</p></blockquote><p>傳給 <a href="./decorators/messages#rawpayload"><code>@rawPayload</code></a> 或 <a href="./decorators/messages#rawheaders"><code>@rawHeaders</code></a> 的 schema，最外層帶有以 <code>#/</code> 開頭的 <code>$ref</code>，但完成的文件在那個位置沒有任何內容。emitter 照原樣複製 raw schema，所以這個 reference 是你寫的。以 <code>#/</code> 開頭的 reference 指向輸出的文件本身，該文件的每個位置都由 emitter 產生。所以 emitter 可以判定這一個不存在。</p><p>常見原因是指向 raw model 自己，例如在 model <code>OrderCreated</code> 上寫 <code>#/components/schemas/OrderCreated</code>。帶 <code>@rawPayload</code> 的 model 不會佔用自己的 <code>components.schemas</code> key。只有在另一個 message 也引用到同一個 model 時，那個位置才存在。</p><p>這個檢查在文件完成後才執行，此時每個區塊都已就位。emitter 只讀 raw schema 的最外層，深度與 <a href="#raw-schema-local-ref"><code>raw-schema-local-ref</code></a> 相同。同時違反兩條規則的 reference 會回報兩次，因為兩條規則各自獨立。</p><p><strong>修法：</strong> 改指向文件實際存在的位置，或直接內嵌定義，不要用 reference。</p><h3 id="raw-payload-lifted-header" tabindex="-1"><code>raw-payload-lifted-header</code> <a class="header-anchor" href="#raw-payload-lifted-header" aria-label="Permalink to &quot;`raw-payload-lifted-header`&quot;">​</a></h3><blockquote><p>The message model &#39;&lt;name&gt;&#39; carries @rawPayload and also lifts @header fields into its <code>headers</code>. The emitter emits the raw payload exactly as written, so it cannot remove the lifted fields from a schema it does not read. The raw payload and the headers are both emitted, and they can describe the same field twice. Describe the headers of &#39;&lt;name&gt;&#39; with @headers or @rawHeaders, or drop the @header marks and let the raw schema carry those fields.</p></blockquote><p>同一個 message 同時有 <code>@rawPayload</code> 與至少一個標了 <code>@header</code> 的欄位。有欄位抽出的 message 平常會取得自己的一份 payload schema，那份 schema 不含被抽出的欄位。raw payload 是不透明的，emitter 無法從中拿掉任何東西。Avro 或 Protobuf 的 record 仍可能宣告 message 已經當成 header 的那個欄位。</p><p>兩邊都照樣輸出。raw payload 原樣進到 message，被抽出的欄位仍然成為 <code>headers</code>。錯誤修好之前不會有任何你寫的東西消失。這一點與 <a href="#duplicate-message-headers"><code>duplicate-message-headers</code></a> 不同，後者兩個來源都不輸出。在那裡，兩個來源填的是同一個欄位。在這裡，兩者填的是兩個不同欄位。</p><p>被抽出的欄位若來自這個 model 繼承的 base message，同樣會回報。</p><p><strong>修法：</strong> 改用 <code>@headers</code> 或 <code>@rawHeaders</code> 描述 headers，或移除 <code>@header</code> 標記，讓 raw schema 承載那些欄位。</p><h3 id="headers-not-object" tabindex="-1"><code>headers-not-object</code> <a class="header-anchor" href="#headers-not-object" aria-label="Permalink to &quot;`headers-not-object`&quot;">​</a></h3><blockquote><p>The model &#39;&lt;name&gt;&#39; given to @headers is backed by an array. AsyncAPI requires the headers schema to be a key/value map, so no <code>headers</code> were emitted. Pass a model with properties instead.</p></blockquote><p>傳給 <code>@headers</code> 的 model 會輸出 <code>type: &quot;array&quot;</code>。它以 array 為底（<code>is</code> 一個 array，或繼承自 array）。AsyncAPI 規定 <code>headers</code> schema 描述一組 key/value map。</p><p><strong>修法：</strong> 改傳一個有屬性的 model，或以 <code>Record&lt;T&gt;</code> 為底的 model。兩者都輸出 object schema。</p><h3 id="discriminated-lifted-header" tabindex="-1"><code>discriminated-lifted-header</code> <a class="header-anchor" href="#discriminated-lifted-header" aria-label="Permalink to &quot;`discriminated-lifted-header`&quot;">​</a></h3><blockquote><p>The message model &#39;&lt;name&gt;&#39; lifts @header fields into its <code>headers</code> and also carries @discriminator. The discriminator names the subtype schemas, and those describe the lifted fields as payload data, so no payload could satisfy the message. The emitter leaves the discriminator off the payload schema. Describe the headers of &#39;&lt;name&gt;&#39; with @headers instead, so its payload keeps every field.</p></blockquote><p>message model 同時帶了 <a href="./decorators/schemas#discriminator"><code>@discriminator</code></a> 並抽出 <code>@header</code> 欄位。discriminator 會把讀取端導向各個子型別的 schema，而每個子型別仍然把被抽出的欄位描述成 payload 資料。這個 message 的任何 payload 都無法滿足它們。</p><p>該關鍵字不會寫進 payload schema。多型仍然透過 model 自己的 component 呈現，那份 component 描述所有欄位。</p><p><strong>修法：</strong> 改用 <a href="./decorators/messages#headers"><code>@headers</code></a> 描述 headers，讓 payload 保留所有欄位。</p><h3 id="content-type-header-conflict" tabindex="-1"><code>content-type-header-conflict</code> <a class="header-anchor" href="#content-type-header-conflict" aria-label="Permalink to &quot;`content-type-header-conflict`&quot;">​</a></h3><blockquote><p>The header &#39;&lt;name&gt;&#39; names the message content type, and this message also carries @contentType. AsyncAPI has one field for the content type, so two sources for it are ambiguous. Remove the @header field and keep @contentType.</p></blockquote><p>某個 header 欄位名為 <code>content-type</code>（比對用輸出的欄位名，且不分大小寫），而同一個 message 又標了 <code>@contentType</code>。AsyncAPI 的 content type 有專屬欄位，兩個來源無法同時成立。<code>@typespec/http</code> 會把這種 header 重新分類，因為 HTTP 沒有別的管道可以表達；本 emitter 有 <code>@contentType</code>，所以直接回報而不自行挑選。</p><p>兩種 headers 機制都會檢查。該欄位可以是 message model 上標了 <code>@header</code> 的欄位，也可以是傳給 <code>@headers</code> 的 model 的屬性，包含該 model 繼承來的屬性。</p><p><strong>修法：</strong> 移除該 header 欄位，保留 <code>@contentType</code>。</p><h3 id="duplicate-correlation-id-decorator" tabindex="-1"><code>duplicate-correlation-id-decorator</code> <a class="header-anchor" href="#duplicate-correlation-id-decorator" aria-label="Permalink to &quot;`duplicate-correlation-id-decorator`&quot;">​</a></h3><blockquote><p>@correlationId is applied to this model more than once. Only one application takes effect, and the rest are discarded. Remove the extra @correlationId.</p></blockquote><p><code>@correlationId</code> 不可重複套用。疊加後只有一次生效，其他的 location 不會進入文件。</p><p><strong>修法：</strong> 移除多餘的 <code>@correlationId</code>。</p><h3 id="invalid-correlation-id-location" tabindex="-1"><code>invalid-correlation-id-location</code> <a class="header-anchor" href="#invalid-correlation-id-location" aria-label="Permalink to &quot;`invalid-correlation-id-location`&quot;">​</a></h3><blockquote><p>&#39;&lt;location&gt;&#39; is not a legal correlation id location, so no <code>correlationId</code> was emitted. Write &#39;$message.header#&#39; or &#39;$message.payload#&#39;, each optionally followed by a JSON Pointer, such as &#39;$message.header#/MQMD/CorrelId&#39;.</p></blockquote><p>這個 location 不符合 AsyncAPI runtime expression 的文法。運算式以 <code>$message.header</code> 或 <code>$message.payload</code> 開頭，後面接一個 <code>#</code>。<code>#</code> 之後是一段 JSON Pointer，所以必須是空字串或以 <code>/</code> 開頭。</p><p><code>#</code> 是必要的。規格的 ABNF 條文看起來像是 fragment 可省略，但規格的正規 JSON Schema 要求 <code>#</code>。官方 AsyncAPI parser 依 JSON Schema 判定，會拒絕帶有 <code>$message.header</code>（不含 <code>#</code>）的文件。</p><p>emitter 只檢查格式：pointer 可以指向任何 schema 都沒宣告的路徑，官方範例本身就這樣寫。</p><p><strong>修法：</strong> 改寫成文法接受的 location，例如 <code>$message.header#/correlationId</code>。</p><h3 id="empty-message-example" tabindex="-1"><code>empty-message-example</code> <a class="header-anchor" href="#empty-message-example" aria-label="Permalink to &quot;`empty-message-example`&quot;">​</a></h3><blockquote><p>This @messageExample carries neither <code>headers</code> nor <code>payload</code>, so it shows nothing about the message. This example was dropped. Give it at least one of the two.</p></blockquote><p>某次 <code>@messageExample</code> 套用給了空值，或只給了 <code>name</code> 與 <code>summary</code>。沒有內容的 Message Example Object 說明不了這個 message。</p><p><strong>修法：</strong> 為該筆範例補上 <code>headers</code>、<code>payload</code>，或兩者都補。</p><h3 id="empty-tag-name" tabindex="-1"><code>empty-tag-name</code> <a class="header-anchor" href="#empty-tag-name" aria-label="Permalink to &quot;`empty-tag-name`&quot;">​</a></h3><blockquote><p>@asyncTag was given an empty name. The <code>name</code> of an AsyncAPI Tag Object is required, and no consumer can match a blank one. This tag was dropped. Give it a name.</p></blockquote><p>某次 <a href="./decorators/document-info#asynctag"><code>@asyncTag</code></a> 套用給了空白的 tag 名稱。值會先去除前後空白，所以只有空白的名稱等同空字串。AsyncAPI Tag Object 的 <code>name</code> 是必填欄位，空白的名稱沒有任何 consumer 比對得到。</p><p><strong>修法：</strong> 為該 tag 補上名稱。</p><h3 id="conflicting-tag-metadata" tabindex="-1"><code>conflicting-tag-metadata</code> <a class="header-anchor" href="#conflicting-tag-metadata" aria-label="Permalink to &quot;`conflicting-tag-metadata`&quot;">​</a></h3><blockquote><p>Tag &#39;&lt;name&gt;&#39; is declared more than once here, with a different &#39;&lt;field&gt;&#39;. AsyncAPI emits one Tag Object per name on an object, so only one of the two values can be kept. The first one in source order was kept. Merge the @asyncTag applications into one, or give them different names.</p></blockquote><p>同一個 target 上兩次套用 <a href="./decorators/document-info#asynctag"><code>@asyncTag</code></a> 指到同一個 tag 名稱，而且同一個欄位給了兩個不同的值。AsyncAPI 在一個物件上，同一個名字只輸出一個 Tag Object，兩個值必定有一個要被丟掉。emitter 回報這個歧義，不自行挑選。</p><p>若兩次套用設定的是<em>不同</em>欄位，則會合併；內建 <code>@tag</code> 與同名的 <code>@asyncTag</code> 也會合併。同一個名字出現在兩個<em>不同</em>的 target 上永遠不算衝突：AsyncAPI 讓每個物件各自持有獨立的 <code>tags</code> 陣列。</p><p><strong>修法：</strong> 把兩次套用合併成一次，或改用不同的名字。</p><h3 id="invalid-extension-key" tabindex="-1"><code>invalid-extension-key</code> <a class="header-anchor" href="#invalid-extension-key" aria-label="Permalink to &quot;`invalid-extension-key`&quot;">​</a></h3><blockquote><p>The extension key &#39;&lt;key&gt;&#39; is not a specification extension name. AsyncAPI reads only a key of the shape &#39;x-&#39; followed by one or more letters, digits, underscores, dots, or hyphens, so this @extension was dropped. Rename the key to that shape.</p></blockquote><p>傳給 <a href="./decorators/document-info#extension"><code>@extension</code></a> 的 key 不符合 AsyncAPI 規格擴充的樣式。樣式是 <code>^x-[\\w\\d\\.\\-\\_]+$</code>。其他 key 在輸出的物件裡都是來歷不明的欄位，官方 parser 會判定整份文件不合法。</p><p>只有 <code>x-</code> 就是這種 key。它有前綴，但後面沒有名字。含空白的 key 也是。</p><p><strong>修法：</strong> 把 key 改成 <code>x-</code> 加上一個以上的英文字母、數字、底線、點或連字號。</p><h3 id="duplicate-extension-key" tabindex="-1"><code>duplicate-extension-key</code> <a class="header-anchor" href="#duplicate-extension-key" aria-label="Permalink to &quot;`duplicate-extension-key`&quot;">​</a></h3><blockquote><p>The extension key &#39;&lt;key&gt;&#39; is applied to this target more than once. An object carries one value per key, so this @extension was dropped and the first one with this key in source order was kept. Remove the extra @extension, or give it another key.</p></blockquote><p>同一個 target 上兩次 <a href="./decorators/document-info#extension"><code>@extension</code></a> 用了同一個 key。輸出的物件對一個 key 只放一個值，兩個值必定有一個要被丟掉。保留原始碼順序中的第一次套用。</p><p>同一個 key 出現在兩個<em>不同</em>的 target 上永遠不算衝突。每個輸出的物件各自持有自己那組擴充欄位。</p><p><strong>修法：</strong> 移除多餘的那次套用，或改用另一個 key。</p><h3 id="duplicate-server-name" tabindex="-1"><code>duplicate-server-name</code> <a class="header-anchor" href="#duplicate-server-name" aria-label="Permalink to &quot;`duplicate-server-name`&quot;">​</a></h3><blockquote><p>Duplicate server name: &#39;&lt;name&gt;&#39;. Each @server on a namespace needs its own name, because the name is the key of that server in the emitted document. This @server was dropped, and the first one with this name in source order was kept.</p></blockquote><p>同一個 namespace 上兩個 <code>@server</code> 用了同一個名稱。名稱就是 <code>servers</code> map 的 key，兩者會互相碰撞。emitter 絕不靜默挑一個。</p><p><strong>修法：</strong> 改掉其中一個的名稱。</p><h3 id="empty-server-field" tabindex="-1"><code>empty-server-field</code> <a class="header-anchor" href="#empty-server-field" aria-label="Permalink to &quot;`empty-server-field`&quot;">​</a></h3><blockquote><p>Empty server field: &#39;&lt;field&gt;&#39;. AsyncAPI requires a value for this field on every server. This @server was dropped.</p></blockquote><p><code>host</code> 或 <code>protocol</code> 是空字串，或只有空白字元。兩者都是 Server Object 的必填欄位。空值可以通過型別檢查，卻會產出不合規的文件，因此整個 server 被丟棄。</p><p><strong>修法：</strong> 給該欄位實際的值。</p><h3 id="invalid-server-name" tabindex="-1"><code>invalid-server-name</code> <a class="header-anchor" href="#invalid-server-name" aria-label="Permalink to &quot;`invalid-server-name`&quot;">​</a></h3><blockquote><p>Invalid server name: &#39;&lt;name&gt;&#39;. AsyncAPI only allows letters, digits, &#39;_&#39;, and &#39;-&#39; in a server name. This @server was dropped.</p></blockquote><p>名稱超出 AsyncAPI 允許的根層 <code>servers</code> map key 字元集。此字元集比 Components Object 的更嚴格，不允許點號。</p><p><strong>修法：</strong> 改用只含英文字母、數字、<code>_</code>、<code>-</code> 的名稱。emitter 絕不自動改名，因為那會靜默換掉你要求的 key。</p><h3 id="empty-channel-address" tabindex="-1"><code>empty-channel-address</code> <a class="header-anchor" href="#empty-channel-address" aria-label="Permalink to &quot;`empty-channel-address`&quot;">​</a></h3><blockquote><p>@channel was given a blank address. A blank address names no topic, path, or routing key, so it cannot reach the emitted document. This channel was dropped. Give it an address, such as &#39;orders.created&#39;, or use @dynamicChannel when the address is only known at runtime.</p></blockquote><p>address 是空字串，或只有空白字元。這個 channel 被丟棄。</p><p><strong>修法：</strong> 給這個 channel 一個 address。位址只有在執行期才決定時，改用 <code>@dynamicChannel</code>。</p><h3 id="invalid-channel-address" tabindex="-1"><code>invalid-channel-address</code> <a class="header-anchor" href="#invalid-channel-address" aria-label="Permalink to &quot;`invalid-channel-address`&quot;">​</a></h3><blockquote><p>The channel address &#39;&lt;address&gt;&#39; carries a query string. AsyncAPI states that a channel address must not use query parameters, and that a channel binding describes them instead. This channel was dropped. Move everything after the &#39;?&#39; into a channel binding.</p></blockquote><p>三種問題會回報這個代碼：address 含 query string、address 含 fragment、<code>{}</code> 不成對或巢狀。訊息會指出是哪一種。三種情況都會丟棄整個 channel。</p><p>scheme 與 host 不檢查。<code>wss://example.com/socket</code> 這樣的完整 URL 是合法的 address。</p><p><strong>修法：</strong> 把 query string 或 fragment 移到 channel binding。讓大括號成對，且不要巢狀。</p><h3 id="invalid-channel-param-name" tabindex="-1"><code>invalid-channel-param-name</code> <a class="header-anchor" href="#invalid-channel-param-name" aria-label="Permalink to &quot;`invalid-channel-param-name`&quot;">​</a></h3><blockquote><p>&#39;&lt;name&gt;&#39; is not a legal channel address parameter name. Only the characters a-z, A-Z, 0-9, &#39;-&#39;, and &#39;_&#39; are allowed, because the name is also the key of that parameter in the emitted <code>parameters</code> map and the name of the TypeSpec property that declares it. This channel was dropped.</p></blockquote><p>address 裡的某個 <code>{name}</code> 超出字元集。這個名稱同時也是宣告該參數的 TypeSpec 屬性名稱，所以超出字元集的名稱永遠不可能被宣告。</p><p><strong>修法：</strong> 把模板名稱改成只含英文字母、數字、<code>-</code>、<code>_</code>。</p><h3 id="empty-channel-id" tabindex="-1"><code>empty-channel-id</code> <a class="header-anchor" href="#empty-channel-id" aria-label="Permalink to &quot;`empty-channel-id`&quot;">​</a></h3><blockquote><p>The channel id given to this decorator is blank. The id is the key of this channel in the emitted <code>channels</code> map, and a blank key names nothing. This channel was dropped. Give it an id, or leave the argument out so the address, or the interface or namespace name for a dynamic channel, is used.</p></blockquote><p>明確指定的 channel id 引數是空字串，或只有空白字元。</p><p><strong>修法：</strong> 給一個 id，或直接省略該引數。省略時 key 用 address。dynamic channel 沒有 address，key 用 interface 或 namespace 的宣告名稱。</p><h3 id="duplicate-channel-decorator" tabindex="-1"><code>duplicate-channel-decorator</code> <a class="header-anchor" href="#duplicate-channel-decorator" aria-label="Permalink to &quot;`duplicate-channel-decorator`&quot;">​</a></h3><blockquote><p>@channel is applied to this interface or namespace more than once. A channel carries one address, so only one application takes effect and the rest are discarded. Remove the extra @channel.</p></blockquote><p><code>@channel</code> 不可重複套用。一個 channel 只有一個 address，疊加會靜默丟掉其餘的 address。</p><p><strong>修法：</strong> 移除多餘的 <code>@channel</code>。第二個 channel 請宣告在第二個 interface 或 namespace 上。</p><h3 id="duplicate-dynamic-channel-decorator" tabindex="-1"><code>duplicate-dynamic-channel-decorator</code> <a class="header-anchor" href="#duplicate-dynamic-channel-decorator" aria-label="Permalink to &quot;`duplicate-dynamic-channel-decorator`&quot;">​</a></h3><blockquote><p>@dynamicChannel is applied to this interface or namespace more than once. Only one application takes effect, and the rest are discarded. Remove the extra @dynamicChannel.</p></blockquote><p><code>@dynamicChannel</code> 不可重複套用，理由與 <code>@channel</code> 相同。</p><p><strong>修法：</strong> 移除多餘的 <code>@dynamicChannel</code>。</p><h3 id="conflicting-channel-decorators" tabindex="-1"><code>conflicting-channel-decorators</code> <a class="header-anchor" href="#conflicting-channel-decorators" aria-label="Permalink to &quot;`conflicting-channel-decorators`&quot;">​</a></h3><blockquote><p>@channel and @dynamicChannel are both applied to this interface or namespace. One states an address and the other states that the address is unknown, and no rule picks a winner, so no channel was emitted at all. Keep one of the two.</p></blockquote><p>兩個 channel decorator 同時標在一個 target 上。一個給了 address，另一個說 address 未知。沒有規則可以判定誰勝出，所以這個 target 完全不輸出 channel。</p><p><strong>修法：</strong> 兩個 decorator 只保留一個。</p><h3 id="duplicate-channel-id" tabindex="-1"><code>duplicate-channel-id</code> <a class="header-anchor" href="#duplicate-channel-id" aria-label="Permalink to &quot;`duplicate-channel-id`&quot;">​</a></h3><blockquote><p>Duplicate channel id: &#39;&lt;id&gt;&#39;. Each channel needs its own id, because the id is the key of that channel in the emitted document. This channel was dropped, and the first one with this id in source order was kept. Pass an explicit id to @channel on one of them.</p></blockquote><p>兩個 channel 對應到同一個 <code>channels</code> map 的 key。常見成因：兩個 channel 共用同一個 address，因為 address 是預設的 key；不同 namespace 下兩個同名的 dynamic channel，因為 channel key 會去掉 namespace 前綴；或兩個明確指定的 id 是同一個字串。</p><p><strong>修法：</strong> 對其中一個的 <code>@channel</code> 或 <code>@dynamicChannel</code> 傳入明確的 id。</p><h3 id="missing-channel-param" tabindex="-1"><code>missing-channel-param</code> <a class="header-anchor" href="#missing-channel-param" aria-label="Permalink to &quot;`missing-channel-param`&quot;">​</a></h3><blockquote><p>The channel address uses &#39;{&lt;name&gt;}&#39;, but no operation in this channel declares a parameter with that name. AsyncAPI requires the <code>parameters</code> map to cover every expression in the address. Add a &#39;&lt;name&gt;&#39; parameter to an operation of this channel, or take the expression out of the address.</p></blockquote><p>address 含一個模板，但這個 channel 的 operation 都沒有宣告它。輸出的 <code>parameters</code> map 仍會涵蓋整個 address，該名稱對應一個空的 Parameter Object。</p><p><strong>修法：</strong> 在這個 channel 的 operation 加上該參數，或把模板從 address 移除。</p><h3 id="unused-channel-param" tabindex="-1"><code>unused-channel-param</code> <a class="header-anchor" href="#unused-channel-param" aria-label="Permalink to &quot;`unused-channel-param`&quot;">​</a></h3><blockquote><p>The parameter &#39;&lt;name&gt;&#39; is not used by the address of channel &#39;&lt;id&gt;&#39;. An operation parameter whose type is not a @message model describes a channel address parameter, and this emitter never rewrites the address to absorb one. Add &#39;{&lt;name&gt;}&#39; to the address, or mark the parameter type with @message.</p></blockquote><p>這個 channel 的 operation 宣告了 address 沒有用到的參數。型別不帶 <code>@message</code> 的頂層 operation 參數一律視為 channel address 參數，所以這個參數無處可去。</p><p><strong>修法：</strong> 把模板加進 address，或在該參數的型別上標 <code>@message</code>，讓它改算成 message。</p><h3 id="non-string-channel-param" tabindex="-1"><code>non-string-channel-param</code> <a class="header-anchor" href="#non-string-channel-param" aria-label="Permalink to &quot;`non-string-channel-param`&quot;">​</a></h3><blockquote><p>The channel parameter &#39;&lt;name&gt;&#39; is not declared as a string. The AsyncAPI Parameter Object has no <code>schema</code> field, so a channel parameter carries no type and its value is always a string. Declare it as a string, a string literal, a union of string literals, or a string-backed enum.</p></blockquote><p>宣告的型別不是字串型別。AsyncAPI Parameter Object 只有 <code>enum</code>、<code>default</code>、<code>description</code>、<code>examples</code>、<code>location</code> 五個欄位，沒有 <code>schema</code>。型別因此無處可放。</p><p><strong>修法：</strong> 把參數宣告成 string、字串字面值、字串字面值的 union，或字串 enum。</p><h3 id="optional-channel-param" tabindex="-1"><code>optional-channel-param</code> <a class="header-anchor" href="#optional-channel-param" aria-label="Permalink to &quot;`optional-channel-param`&quot;">​</a></h3><blockquote><p>The channel parameter &#39;&lt;name&gt;&#39; is optional. A Channel Address Expression is a bare &#39;{name}&#39; with no operator, so a separator next to it cannot disappear along with the value, whatever the position in the address. Make the parameter required, and give the Parameter Object a <code>default</code> through a TypeSpec default value if it usually carries one value.</p></blockquote><p>宣告是選填的。不論模板在 address 的哪個位置，這都是錯誤。Channel Address Expression 只允許裸的 <code>{name}</code>，沒有 RFC 6570 的 operator，所以分隔字元無法跟著缺席的值一起消失。</p><p><strong>修法：</strong> 把參數改成必填。若它經常是同一個值，給它 TypeSpec 預設值。該值會成為 Parameter Object 的 <code>default</code>。</p><h3 id="conflicting-channel-param" tabindex="-1"><code>conflicting-channel-param</code> <a class="header-anchor" href="#conflicting-channel-param" aria-label="Permalink to &quot;`conflicting-channel-param`&quot;">​</a></h3><blockquote><p>The channel parameter &#39;&lt;name&gt;&#39; is declared more than once in channel &#39;&lt;id&gt;&#39;, with a different &#39;&lt;field&gt;&#39;. AsyncAPI emits one Parameter Object per name on a channel, so only one of the two values can be kept. The first one in source order was kept. Give the two declarations the same type, default, documentation, examples, and location.</p></blockquote><p>同一個 channel 的兩個 operation 宣告同一個參數名稱，但兩處的型別、預設值、<code>@doc</code>、<code>@example</code> 或 <code>@parameterLocation</code> 不同。一個 channel 對一個名稱只輸出一個 Parameter Object，兩個值只能留一個。保留原始碼順序在前的那一個，讓文件其餘部分仍可閱讀。</p><p>型別的比較依據是它允許的值，不是它的寫法。兩個 operation 各自寫一次 <code>&quot;eu&quot; | &quot;us&quot;</code>，兩者視為一致。</p><p><strong>修法：</strong> 讓兩處宣告的型別、預設值、說明、範例與 location 一致。</p><h3 id="duplicate-parameter-location-decorator" tabindex="-1"><code>duplicate-parameter-location-decorator</code> <a class="header-anchor" href="#duplicate-parameter-location-decorator" aria-label="Permalink to &quot;`duplicate-parameter-location-decorator`&quot;">​</a></h3><blockquote><p>@parameterLocation is applied to this property more than once. A channel parameter carries one location, so only one application takes effect and the rest are discarded. Remove the extra @parameterLocation.</p></blockquote><p><code>@parameterLocation</code> 不可重複套用。一個 Parameter Object 只有一個 <code>location</code> 欄位。</p><p><strong>修法：</strong> 移除多餘的 <code>@parameterLocation</code>。</p><h3 id="invalid-parameter-location" tabindex="-1"><code>invalid-parameter-location</code> <a class="header-anchor" href="#invalid-parameter-location" aria-label="Permalink to &quot;`invalid-parameter-location`&quot;">​</a></h3><blockquote><p>&#39;&lt;location&gt;&#39; is not a legal channel parameter location, so no <code>location</code> was emitted. Write &#39;$message.header#&#39; or &#39;$message.payload#&#39;, each optionally followed by a JSON Pointer, such as &#39;$message.payload#/user/id&#39;.</p></blockquote><p>runtime expression 超出文法。開頭必須是 <code>$message.header#</code> 或 <code>$message.payload#</code>，後面可以接 JSON Pointer。<code>#</code> 是必要的，因為規格的規範性 JSON Schema 要求它。</p><p><strong>修法：</strong> 照該格式撰寫，例如 <code>$message.payload#/user/id</code>。</p><h3 id="duplicate-send-decorator" tabindex="-1"><code>duplicate-send-decorator</code> <a class="header-anchor" href="#duplicate-send-decorator" aria-label="Permalink to &quot;`duplicate-send-decorator`&quot;">​</a></h3><blockquote><p>@send is applied to this operation more than once. An operation carries one action, so only one application takes effect and the rest are discarded. Remove the extra @send.</p></blockquote><p><code>@send</code> 不可重複套用。一個 Operation Object 只有一個 <code>action</code> 欄位。</p><p><strong>修法：</strong> 移除多餘的 <code>@send</code>。</p><h3 id="duplicate-receive-decorator" tabindex="-1"><code>duplicate-receive-decorator</code> <a class="header-anchor" href="#duplicate-receive-decorator" aria-label="Permalink to &quot;`duplicate-receive-decorator`&quot;">​</a></h3><blockquote><p>@receive is applied to this operation more than once. An operation carries one action, so only one application takes effect and the rest are discarded. Remove the extra @receive.</p></blockquote><p><code>@receive</code> 不可重複套用，理由與 <code>@send</code> 相同。</p><p><strong>修法：</strong> 移除多餘的 <code>@receive</code>。</p><h3 id="conflicting-operation-actions" tabindex="-1"><code>conflicting-operation-actions</code> <a class="header-anchor" href="#conflicting-operation-actions" aria-label="Permalink to &quot;`conflicting-operation-actions`&quot;">​</a></h3><blockquote><p>@send and @receive are both applied to this operation. One states that this application sends the message and the other states that it receives one, and no rule picks a winner, so no operation was emitted at all. Keep one of the two.</p></blockquote><p>兩個 decorator 宣告相反的方向。沒有規則可以判定誰勝出，所以這個 operation 直接被丟棄，不會輸出任意一個 action。</p><p><strong>修法：</strong> 只保留其中一個。同一個 channel 上的兩個方向是兩個 operation，另一個方向請另外寫一個 operation。</p><h3 id="empty-operation-id" tabindex="-1"><code>empty-operation-id</code> <a class="header-anchor" href="#empty-operation-id" aria-label="Permalink to &quot;`empty-operation-id`&quot;">​</a></h3><blockquote><p>The operation id given to this decorator is blank. The id is the key of this operation in the emitted <code>operations</code> map, and a blank key names nothing. This operation was dropped. Give it an id, or leave the argument out so the operation name is used.</p></blockquote><p>id 是這個 operation 在輸出文件中的 key。空白的 key 沒有指到任何東西。</p><p><strong>修法：</strong> 給引數一個 id，或整個省略引數，改用 operation 名稱。</p><h3 id="duplicate-operation-id" tabindex="-1"><code>duplicate-operation-id</code> <a class="header-anchor" href="#duplicate-operation-id" aria-label="Permalink to &quot;`duplicate-operation-id`&quot;">​</a></h3><blockquote><p>Duplicate operation id: &#39;&lt;id&gt;&#39;. Each operation needs its own id, because the id is the key of that operation in the emitted document. This operation was dropped, and the first one with this id in source order was kept. Pass an explicit id to @send or @receive on one of them.</p></blockquote><p>兩個 operation 對應到同一個 key。key 來自明確的 id 引數，沒給時來自 operation 名稱。原始碼順序在前的保留該 key。</p><p><strong>修法：</strong> 在其中一個的 <code>@send</code> 或 <code>@receive</code> 上傳入明確的 id。</p><h3 id="duplicate-reply-channel-decorator" tabindex="-1"><code>duplicate-reply-channel-decorator</code> <a class="header-anchor" href="#duplicate-reply-channel-decorator" aria-label="Permalink to &quot;`duplicate-reply-channel-decorator`&quot;">​</a></h3><blockquote><p>@replyChannel is applied to this operation more than once. A reply points at one channel, so only one application takes effect and the rest are discarded. Remove the extra @replyChannel.</p></blockquote><p><code>@replyChannel</code> 不可重複套用。一個 Operation Reply Object 只有一個 <code>channel</code> 欄位。</p><p><strong>修法：</strong> 移除多餘的 <code>@replyChannel</code>。</p><h3 id="duplicate-reply-address-decorator" tabindex="-1"><code>duplicate-reply-address-decorator</code> <a class="header-anchor" href="#duplicate-reply-address-decorator" aria-label="Permalink to &quot;`duplicate-reply-address-decorator`&quot;">​</a></h3><blockquote><p>@replyAddress is applied to this operation more than once. A reply carries one address, so only one application takes effect and the rest are discarded. Remove the extra @replyAddress.</p></blockquote><p><code>@replyAddress</code> 不可重複套用。一個 Operation Reply Object 只有一個 <code>address</code> 欄位。</p><p><strong>修法：</strong> 移除多餘的 <code>@replyAddress</code>。</p><h3 id="invalid-reply-address-location" tabindex="-1"><code>invalid-reply-address-location</code> <a class="header-anchor" href="#invalid-reply-address-location" aria-label="Permalink to &quot;`invalid-reply-address-location`&quot;">​</a></h3><blockquote><p>&#39;&lt;location&gt;&#39; is not a legal reply address location, so no <code>address</code> was emitted on the reply. Write &#39;$message.header#&#39; or &#39;$message.payload#&#39;, each optionally followed by a JSON Pointer, such as &#39;$message.header#/replyTo&#39;.</p></blockquote><p>runtime expression 超出文法。開頭必須是 <code>$message.header#</code> 或 <code>$message.payload#</code>，後面可以接 JSON Pointer。這與 <code>@correlationId</code> 和 <code>@parameterLocation</code> 的文法相同。</p><p><strong>修法：</strong> 照該格式撰寫，例如 <code>$message.header#/replyTo</code>。</p><p>以下五個代碼來自通訊協定 binding，另有兩個列在「警告」章節。回報它們的 decorator 見<a href="/zh-tw/reference/bindings/">通訊協定 binding</a>。</p><h3 id="duplicate-binding" tabindex="-1"><code>duplicate-binding</code> <a class="header-anchor" href="#duplicate-binding" aria-label="Permalink to &quot;`duplicate-binding`&quot;">​</a></h3><blockquote><p>The protocol &#39;&lt;protocol&gt;&#39; already has a binding at the &lt;level&gt; level on this target. A Bindings Object carries one member per protocol, and two configurations are neither merged nor allowed to overwrite each other. This binding was dropped, and the first one in source order was kept. Keep one of the two, and note that @binding(&quot;&lt;protocol&gt;&quot;, ...) claims the same member as the decorator named after that protocol.</p></blockquote><p>同一個 target 的同一層級上，一個通訊協定被宣告兩次。<code>@binding(&quot;kafka&quot;, ...)</code> 與 <code>@kafkaChannel</code> 並存也是同一個錯誤，因為兩者都寫 <code>kafka</code> 成員。</p><p><strong>修法：</strong> 兩個 decorator 只留一個。</p><h3 id="empty-binding-protocol" tabindex="-1"><code>empty-binding-protocol</code> <a class="header-anchor" href="#empty-binding-protocol" aria-label="Permalink to &quot;`empty-binding-protocol`&quot;">​</a></h3><blockquote><p>The protocol name given to @binding is blank. The name becomes a member name of the emitted <code>bindings</code> object, and a blank member name is not legal. This binding was dropped. Name the protocol, such as <code>kafka</code> or <code>mqtt</code>.</p></blockquote><p>通訊協定名稱會成為輸出文件中的 key。空白的 key 沒有指到任何東西。</p><p><strong>修法：</strong> 填入通訊協定名稱。</p><h3 id="invalid-binding-config" tabindex="-1"><code>invalid-binding-config</code> <a class="header-anchor" href="#invalid-binding-config" aria-label="Permalink to &quot;`invalid-binding-config`&quot;">​</a></h3><blockquote><p>The config given to @binding(&quot;&lt;protocol&gt;&quot;, ...) is not an object. Every member of a Bindings Object is an object, so this binding was dropped. Write the config as an object value, such as #{ qos: 2 }.</p></blockquote><p>AsyncAPI 規定 Bindings Object 的每個成員都是物件。字串、數字與陣列都會被拒絕。</p><p><strong>修法：</strong> 把設定寫成物件值。</p><h3 id="invalid-required-binding-field" tabindex="-1"><code>invalid-required-binding-field</code> <a class="header-anchor" href="#invalid-required-binding-field" aria-label="Permalink to &quot;`invalid-required-binding-field`&quot;">​</a></h3><blockquote><p>The &lt;protocol&gt; binding field &#39;&lt;field&gt;&#39; expects &lt;expected&gt;. The value given here is outside that. The binding cannot be written without the field, so the whole binding was dropped. Write &#39;&lt;field&gt;&#39; as &lt;expected&gt;.</p></blockquote><p>某個欄位的值違反 binding 規格。少了這個欄位，emitter 就寫不出這個 binding，所以丟掉的是整個 binding，不是單一欄位。這一點與 <a href="#invalid-binding-field"><code>invalid-binding-field</code></a> 不同，那個代碼是警告，而且會保留 binding 的其餘部分。</p><p>會回報它的欄位有：Amazon SQS channel 的 <code>queue</code> 與 <code>deadLetterQueue</code>、SQS operation 的 <code>queues</code>、Google Cloud Pub/Sub channel 的 <code>schemaSettings</code>，以及 Pulsar channel 的 <code>persistence</code>。<code>deadLetterQueue</code> 雖然是選填，代價一樣是整個 binding。作者既然寫了這個佇列，少了它的 binding 就比原始碼描述得更少。</p><p><strong>修法：</strong> 依訊息指出的範圍填值。</p><h3 id="missing-binding-field" tabindex="-1"><code>missing-binding-field</code> <a class="header-anchor" href="#missing-binding-field" aria-label="Permalink to &quot;`missing-binding-field`&quot;">​</a></h3><blockquote><p>The &lt;protocol&gt; binding requires the field &#39;&lt;field&gt;&#39;, and this binding does not give it. AsyncAPI would reject the emitted document, so the whole binding was dropped. Add &#39;&lt;field&gt;&#39; to the decorator config.</p></blockquote><p>有幾個 binding 規定了作者必須給的欄位。Pulsar channel 需要 <code>namespace</code> 與 <code>persistence</code>。Google Cloud Pub/Sub channel 需要 <code>schemaSettings</code>，而該物件又需要 <code>encoding</code> 與 <code>name</code>。Amazon SQS channel 需要 <code>queue</code>，而該 queue 又需要 <code>name</code> 與 <code>fifoQueue</code>。SQS operation 需要至少有一筆的 <code>queues</code> 清單。JMS server 需要 <code>jmsConnectionFactory</code>。</p><p>空白字串等同於沒寫。全是空格的名稱沒有指名任何東西，價值不高於完全不寫該欄位。</p><p>同一個物件缺的每個欄位都會回報，不是只報第一個。一次只報一個會讓作者多跑一輪。</p><p><strong>修法：</strong> 依訊息指名的欄位，補進 decorator 的設定裡。</p><h3 id="duplicate-security-scheme-name" tabindex="-1"><code>duplicate-security-scheme-name</code> <a class="header-anchor" href="#duplicate-security-scheme-name" aria-label="Permalink to &quot;`duplicate-security-scheme-name`&quot;">​</a></h3><blockquote><p>Duplicate security scheme name: &#39;&lt;name&gt;&#39;. Each @securityScheme needs its own name, because the name is the key of that scheme in components.securitySchemes. This @securityScheme was dropped, and the first one with this name in source order was kept.</p></blockquote><p>兩個 <code>@securityScheme</code> 用了同一個名稱。名稱就是 <code>components.securitySchemes</code> map 的 key，兩者會相撞。scheme 是跨整個程式收集的，因此標在不同 namespace 上也算重名。</p><p><strong>修法：</strong> 其中一個改名。</p><h3 id="invalid-security-scheme-name" tabindex="-1"><code>invalid-security-scheme-name</code> <a class="header-anchor" href="#invalid-security-scheme-name" aria-label="Permalink to &quot;`invalid-security-scheme-name`&quot;">​</a></h3><blockquote><p>Invalid security scheme name: &#39;&lt;name&gt;&#39;. AsyncAPI only allows letters, digits, &#39;.&#39;, &#39;-&#39;, and &#39;_&#39; in a components key. This decorator was dropped.</p></blockquote><p>名稱超出 AsyncAPI 允許的 Components Object key 字元集。此處允許點號，根層 <code>servers</code> map 的 key 則不允許。</p><p>有兩個 decorator 會回報這條診斷。<code>@securityScheme</code> 把名稱寫成 <code>components.securitySchemes</code> 的 key。<code>@useSecurity</code> 把名稱寫進指向該 key 的 JSON Pointer，字元集以外的字元會讓 pointer 格式錯誤。</p><p><strong>修法：</strong> 改用只含英文字母、數字、<code>.</code>、<code>-</code>、<code>_</code> 的名稱。emitter 絕不自動改名。</p><h3 id="empty-security-scheme-field" tabindex="-1"><code>empty-security-scheme-field</code> <a class="header-anchor" href="#empty-security-scheme-field" aria-label="Permalink to &quot;`empty-security-scheme-field`&quot;">​</a></h3><blockquote><p>Empty security scheme field: &#39;&lt;field&gt;&#39;. AsyncAPI requires a value for this field on this kind of scheme. This @securityScheme was dropped.</p></blockquote><p>scheme 的必填字串欄位是空字串，或只有空白字元。涵蓋 <code>httpApiKey</code> 的 <code>name</code>、<code>http</code> 的 <code>scheme</code>、<code>openIdConnect</code> 的 <code>openIdConnectUrl</code>。空白值可以通過型別檢查，卻讓文件不合規格。</p><p><strong>修法：</strong> 給該欄位一個值。</p><h3 id="missing-oauth-flow-url" tabindex="-1"><code>missing-oauth-flow-url</code> <a class="header-anchor" href="#missing-oauth-flow-url" aria-label="Permalink to &quot;`missing-oauth-flow-url`&quot;">​</a></h3><blockquote><p>The &#39;&lt;flow&gt;&#39; OAuth flow needs a &#39;&lt;field&gt;&#39;. A blank value counts as a missing one, because no client can call it. This @securityScheme was dropped.</p></blockquote><p>OAuth flow 缺少該 flow 必填的 URL。<code>implicit</code> 與 <code>authorizationCode</code> 需要 <code>authorizationUrl</code>。<code>password</code>、<code>clientCredentials</code>、<code>authorizationCode</code> 需要 <code>tokenUrl</code>。</p><p><strong>修法：</strong> 補上該 flow 需要的 URL。</p><h3 id="empty-oauth-flows" tabindex="-1"><code>empty-oauth-flows</code> <a class="header-anchor" href="#empty-oauth-flows" aria-label="Permalink to &quot;`empty-oauth-flows`&quot;">​</a></h3><blockquote><p>This oauth2 scheme declares no flow. A client then has no way to obtain a token. This @securityScheme was dropped. Declare at least one of <code>implicit</code>, <code>password</code>, <code>clientCredentials</code>, and <code>authorizationCode</code>.</p></blockquote><p><code>oauth2</code> scheme 的 <code>flows</code> 是空物件。</p><p><strong>修法：</strong> 至少宣告一個 flow。</p><h3 id="invalid-url" tabindex="-1"><code>invalid-url</code> <a class="header-anchor" href="#invalid-url" aria-label="Permalink to &quot;`invalid-url`&quot;">​</a></h3><blockquote><p>The &#39;&lt;field&gt;&#39; value &#39;&lt;url&gt;&#39; is not an absolute URL. AsyncAPI requires an absolute URL here, and a parser rejects the whole document over a relative one. This decorator was dropped. Write a URL with a scheme, such as &#39;<a href="https://example.com/token" target="_blank" rel="noreferrer">https://example.com/token</a>&#39;.</p></blockquote><p>URL 欄位的值不是絕對 URL。相對路徑（例如 <code>/token</code>）不合格，純文字也不合格。AsyncAPI 對這些欄位標了 <code>uri</code> 格式。值不合格時，parser 會拒絕整份文件。</p><p>三個 decorator 會回報這個診斷。<code>@securityScheme</code> 檢查 <code>openIdConnectUrl</code>，也檢查每個 OAuth flow 的 <code>authorizationUrl</code>、<code>tokenUrl</code> 與 <code>refreshUrl</code>。flow 的 URL 會連 flow 名稱一起標示，例如 <code>implicit.authorizationUrl</code>。<code>@externalDocs</code> 檢查它帶的連結，該連結會寫進 <code>info</code> 與每一個 server。<code>@info</code> 檢查 <code>termsOfService</code>、<code>contact.url</code> 與 <code>license.url</code>。</p><p><code>@info</code> 只丟掉該欄位，decorator 的其餘部分保留。另外兩個會丟掉整個 decorator。訊息本身會說明是哪一種。</p><p><strong>修法：</strong> 把 URL 寫成含 scheme 的形式，例如 <code>https://example.com/token</code>。</p><h3 id="empty-info-version" tabindex="-1"><code>empty-info-version</code> <a class="header-anchor" href="#empty-info-version" aria-label="Permalink to &quot;`empty-info-version`&quot;">​</a></h3><blockquote><p>@info was given a blank version. The <code>version</code> of an AsyncAPI Info Object is required, and a blank one names no version of the application. The version falls back to the document default. Give it a version, such as &#39;1.0.0&#39;.</p></blockquote><p><code>@info</code> 拿到的 <code>version</code> 是空白。值會先去除前後空白，所以只有空白的值等同空字串。AsyncAPI 規定這個欄位必填，所以版本後備為 <code>0.0.0</code>。</p><p><strong>修法：</strong> 給 <code>@info</code> 一個版本，例如 <code>1.0.0</code>。</p><h3 id="empty-license-name" tabindex="-1"><code>empty-license-name</code> <a class="header-anchor" href="#empty-license-name" aria-label="Permalink to &quot;`empty-license-name`&quot;">​</a></h3><blockquote><p>@info was given a license with a blank name. The <code>name</code> of an AsyncAPI License Object is required, and a blank one names no license. The whole license was dropped, and the rest of the decorator was kept. Give the license a name, such as &#39;MIT&#39;.</p></blockquote><p><code>@info</code> 拿到的 <code>license</code> 帶了空白的 <code>name</code>。值會先去除前後空白，所以只有空白的值等同空字串。AsyncAPI 規定這個欄位必填，沒有名稱的 License Object 指不到任何授權條款。</p><p>整個 license 會被丟掉，<code>license.url</code> 也一起丟掉。<code>@info</code> 的其餘部分保留。</p><p><strong>修法：</strong> 給授權條款一個名稱，例如 <code>MIT</code>。</p><h3 id="duplicate-info-decorator" tabindex="-1"><code>duplicate-info-decorator</code> <a class="header-anchor" href="#duplicate-info-decorator" aria-label="Permalink to &quot;`duplicate-info-decorator`&quot;">​</a></h3><blockquote><p>@info is applied to this namespace more than once. A document carries one Info Object, so only one application takes effect and the rest are discarded. Remove the extra @info.</p></blockquote><p>同一個 namespace 套用了多次 <code>@info</code>。一份文件只有一個 Info Object，所以只有一次套用會生效。同一個宣告上的 decorator 由下往上執行，所以寫在最後的那次先執行並勝出。</p><p><strong>修法：</strong> 把多次套用合併成一次，移除多餘的 <code>@info</code>。</p><h3 id="conflicting-generated-schema-source" tabindex="-1"><code>conflicting-generated-schema-source</code> <a class="header-anchor" href="#conflicting-generated-schema-source" aria-label="Permalink to &quot;`conflicting-generated-schema-source`&quot;">​</a></h3><blockquote><p>Two preview features generate the payload schema of this model: &#39;&lt;first&gt;&#39; and &#39;&lt;second&gt;&#39;. There is no order between them, so the emitter cannot choose one. Turn one of the two off in <code>preview-features</code> in <code>tspconfig.yaml</code>.</p></blockquote><p>有兩個<a href="./emitter-options#預覽功能">預覽功能</a>為同一個 model 產生 payload schema。</p><p>emitter 兩個都不採用。要選出勝者，只能看 emitter 列出 provider 的順序，而那個順序不是專案講出來的。</p><p>這時不會輸出文件。兩份 artifact 都丟掉，model 退回 TypeSpec 型別產生的 schema。那份輸出等於答非所問。</p><p><strong>修法：</strong> 從 <code>tspconfig.yaml</code> 的 <code>preview-features</code> 移除其中一個名稱。</p><h3 id="preview-feature-unavailable" tabindex="-1"><code>preview-feature-unavailable</code> <a class="header-anchor" href="#preview-feature-unavailable" aria-label="Permalink to &quot;`preview-feature-unavailable`&quot;">​</a></h3><blockquote><p>The preview feature &#39;&lt;feature&gt;&#39; is not available in this release. It is a name this emitter reserves, and the provider behind it is not built yet. Remove &#39;&lt;feature&gt;&#39; from <code>preview-features</code> in <code>tspconfig.yaml</code>.</p></blockquote><p><a href="./emitter-options#預覽功能"><code>preview-features</code></a> 選項指名了一個本版沒有實作的功能。保留的名稱是 <code>protobuf</code> 與 <code>avro</code>。這兩個在本版都已經實作，所以目前沒有名稱會回報這條診斷。不在保留集合裡的名稱會先被選項 schema 擋下，不會走到這條診斷。</p><p>不會寫出任何檔案。在這個錯誤旁邊輸出一份文件，等於忽略了請求卻不說明。</p><p><strong>修法：</strong> 從 <code>tspconfig.yaml</code> 的 <code>preview-features</code> 移除該名稱。</p><h3 id="protobuf-artifact-unavailable" tabindex="-1"><code>protobuf-artifact-unavailable</code> <a class="header-anchor" href="#protobuf-artifact-unavailable" aria-label="Permalink to &quot;`protobuf-artifact-unavailable`&quot;">​</a></h3><blockquote><p>Model &#39;&lt;name&gt;&#39; carries @Protobuf.message, and no namespace above it carries @Protobuf.package. A generated payload is the proto3 text of a whole package, so the model needs one. Add @Protobuf.package to the namespace that holds this model.</p></blockquote><blockquote><p>Model &#39;&lt;name&gt;&#39; of package &#39;&lt;package&gt;&#39; reaches &lt;construct&gt;, and proto3 has nothing this emitter can write it as. So this message has no generated payload. Describe that part with a construct proto3 covers, or remove @Protobuf.message from the model.</p></blockquote><blockquote><p>Scalar &#39;&lt;scalar&gt;&#39; has no proto3 type, and no scalar it extends has one either. So model &#39;&lt;name&gt;&#39; of package &#39;&lt;package&gt;&#39; has no generated payload. Give the field a scalar that extends one of the Protobuf scalar types.</p></blockquote><p>三種問題會回報這個代碼，訊息會指出是哪一種：model 上層沒有 package、model 走到寫不成 proto3 的構造、欄位用了對映不到 proto3 型別的 scalar。</p><p>第二種訊息會指出它停在哪個構造。這個 emitter 寫的是單一 payload 的 proto3 文字，那份文字不含 <code>import</code> 行。在那裡沒有誠實形式的構造一律拒絕：</p><ul><li>union，以及其他 proto3 沒有對應形式的屬性型別</li><li>匿名 model</li><li>template 執行個體</li><li>帶 <code>@Protobuf.externRef</code> 的型別，包含 well known 型別</li><li>沒有 <code>@Protobuf.field</code> 編號的屬性</li><li><code>Protobuf.Map</code> 的陣列，proto3 沒有這種形式</li><li>巢狀在其他型別裡的 <code>Protobuf.Map</code>，例如另一個 map 的值</li><li>用 proto3 不能當 map key 的型別當 key 的 <code>Protobuf.Map</code></li><li>值是陣列的 <code>Protobuf.Map</code>，因為 map 的值不帶 label</li><li>沒有 key 和 value 的 <code>Protobuf.Map</code></li><li>傳進值而不是型別的 <code>Protobuf.Map</code></li><li>屬於其他 Protobuf package 的 model 或 enum</li><li>沒有任何 <code>@Protobuf.package</code> 涵蓋的 model 或 enum</li><li>名稱已被同一份 payload 的另一個宣告佔用的 model 或 enum</li><li>第一個變體不是零的 enum</li><li>有非整數變體的 enum</li><li>這個 emitter 讀不懂的 <code>@Protobuf.package</code> 宣告</li><li>這個 emitter 讀不懂的 <code>@Protobuf.reserve</code> 列表</li></ul><p>其中四項指的是這個 emitter 讀不懂的 state：沒有 key 和 value 的 <code>Protobuf.Map</code>、傳進值而不是型別的 <code>Protobuf.Map</code>、<code>@Protobuf.package</code> 宣告，以及 <code>@Protobuf.reserve</code> 列表。那些 state 屬於另一個 library，那個 library 對它的形狀沒有任何承諾。遇到讀不懂的形狀就拒絕，不猜：猜錯會把錯的 proto3 文字寫進文件，而且不會有任何地方講出來。</p><p>第三種訊息會指出是哪個 scalar。這個 emitter 對映 Protobuf library 對映的那 15 個 scalar。其中九個是 TypeSpec 內建的 scalar，六個來自 Protobuf library。它也會沿著自訂 scalar 的 extends 鏈往上找。整條鏈都碰不到那 15 個的 scalar，沒有型別可寫。</p><p>只帶 <code>@Protobuf.message</code>、沒有 <code>@AsyncAPI.message</code> 的 model 不會收到任何診斷。它沒有要求 payload，所以拿官方 decorator 描述其他型別的專案不會因此建置失敗。</p><p><code>protobuf</code> 預覽功能在收集產生的 payload 時回報這條診斷。被指名的 model 拿不到產生的 payload。emitter 回報問題，不寫出空的 payload，因為空 payload 讀起來像一份什麼都沒描述的 schema。</p><p>model 屬於哪個 package，由上層最近一個帶 <code>@Protobuf.package</code> 的 namespace 決定。這個 emitter 讀 decorator state，所以改名過的 package 以它宣告的名稱比對。</p><p><strong>修法：</strong> 在 model 所在的 namespace 加上 <code>@Protobuf.package</code>。另外兩種訊息則改寫訊息指名的型別，或從該 model 移除 <code>@Protobuf.message</code>。</p><h3 id="header-on-generated-payload" tabindex="-1"><code>header-on-generated-payload</code> <a class="header-anchor" href="#header-on-generated-payload" aria-label="Permalink to &quot;`header-on-generated-payload`&quot;">​</a></h3><blockquote><p>Property &#39;&lt;name&gt;&#39; of message &#39;&lt;message&gt;&#39; carries @header, and the model carries &lt;decorator&gt;. A header travels beside the payload, and neither Protobuf nor Avro has a way to describe a property the payload does not carry. Move the headers into their own model and point at it with @headers.</p></blockquote><p>一個 message model 在自己的欄位上寫了 <code>@header</code>，同時又帶著 <code>@Protobuf.message</code> 或 <code>@Avro.avroRecord</code>。</p><p><code>@header</code> 說明那個屬性走在 payload 旁邊。兩種目標語言都沒有這個概念。Protobuf 給 message 的每個屬性一個欄位編號，Avro 給 record 的每個屬性一個 field，所以一個 payload 不帶的屬性既沒有位置可放，也沒有辦法標記成不存在。</p><p>另一個選項是把屬性從產生的 schema 裡省略，那更糟。<code>@typespec/protobuf</code> 與 Avro emitter 都寫出完整的 model，兩者都不讀 AsyncAPI decorator。這樣文件裡的 schema 與獨立的檔案會描述同一個 message 的不同形狀，而兩個檔案都不會說出這件事。</p><p>每個被標記的屬性都會被指名。修好一個再編譯一次找下一個，這個來回可以省下來。</p><p>這是在任何 emitter 執行之前回報的。所以它對「輸出文件」、「只輸出 schema 檔案」、「什麼都不輸出」三種專案一律成立。不會寫出任何檔案。</p><p>標在 message 碰到的其他 model 上是另一回事。那個 model 不是 message，標記在那裡沒有意義，改由 <a href="#nested-header-ignored"><code>nested-header-ignored</code></a> 回報。</p><p><strong>修法：</strong> 把 headers 移進自己的 model，用 <code>@headers</code> 指向它。這樣 message model 只裝 payload，而每個檔案的寫出者對「哪些欄位屬於哪裡」的看法一致。</p><h3 id="avro-artifact-unavailable" tabindex="-1"><code>avro-artifact-unavailable</code> <a class="header-anchor" href="#avro-artifact-unavailable" aria-label="Permalink to &quot;`avro-artifact-unavailable`&quot;">​</a></h3><blockquote><p>Model &#39;&lt;name&gt;&#39; carries @Avro.avroRecord, and the Avro walk refused it: &lt;reason&gt; So this message has no generated payload. Describe that part with a construct Avro covers, or remove @Avro.avroRecord from the model. Emitting the Avro files themselves reports every reason rather than the first.</p></blockquote><p>某個 model 同時有 <code>@Avro.avroRecord</code> 與 <code>@AsyncAPI.message</code>，而 <code>tsp-avro</code> 拒絕替它建出 schema。訊息裡引述的原因來自那個套件。</p><p>只引述第一條原因。Avro 的走訪遇到拒絕之後會繼續走，所以一個 model 可能累積多條。要讀到全部，把 <code>tsp-avro</code> 放進 <code>emit</code> 再編譯一次。</p><p>不會寫出文件。那個 model 的 payload 會退回成它的 TypeSpec 型別產生的 schema。那份檔案用一般的 JSON Schema 回應了一個要求 Avro 的請求，而且檔案裡沒有任何一處說明這件事。</p><p>只有 <code>@Avro.avroRecord</code> 而沒有 <code>@AsyncAPI.message</code> 的 model 不會回報任何東西。它沒有要求任何 payload，所以替其他型別寫 Avro record 的專案不會因此變紅。</p><p><strong>修法：</strong> 修改原因指出的那個部分，或是從 model 移除 <code>@Avro.avroRecord</code>。</p><h3 id="avro-library-missing" tabindex="-1"><code>avro-library-missing</code> <a class="header-anchor" href="#avro-library-missing" aria-label="Permalink to &quot;`avro-library-missing`&quot;">​</a></h3><blockquote><p>The preview feature &#39;avro&#39; is on, and &#39;tsp-avro&#39; could not be loaded: &lt;reason&gt; That library holds the Avro walk, and this emitter carries no copy of it. Install &#39;tsp-avro&#39; beside this emitter, or remove &#39;avro&#39; from <code>preview-features</code> in <code>tspconfig.yaml</code>.</p></blockquote><p><a href="./emitter-options#預覽功能"><code>preview-features</code></a> 選項指名了 <code>avro</code>，而載入 <code>tsp-avro</code> 失敗。訊息會引述載入時回報的內容。</p><p><code>tsp-avro</code> 是這個 emitter 的選用 peer dependency。只有功能開啟時才會載入它，所以沒開這個功能的專案完全不需要它。開啟這個功能的專案要自己安裝。</p><p>不會寫出文件。專案要求的每一份 Avro payload 都不在，而少了它們的文件描述的是另一件事。</p><p><strong>修法：</strong> 安裝 <code>tsp-avro</code>，或是從 <code>tspconfig.yaml</code> 的 <code>preview-features</code> 移除 <code>avro</code>。</p><h2 id="警告" tabindex="-1">警告 <a class="header-anchor" href="#警告" aria-label="Permalink to &quot;警告&quot;">​</a></h2><h3 id="duplicate-channel-address" tabindex="-1"><code>duplicate-channel-address</code> <a class="header-anchor" href="#duplicate-channel-address" aria-label="Permalink to &quot;`duplicate-channel-address`&quot;">​</a></h3><blockquote><p>Channel &#39;&lt;id&gt;&#39; and channel &#39;&lt;other&gt;&#39; both use the address &#39;&lt;address&gt;&#39;. AsyncAPI allows it, because the two have different ids, but a reader cannot tell which set of messages one address actually carries. Give them one channel with both operations, or give each its own address.</p></blockquote><p>兩個 channel 用了同一個 address。文件仍然合法，因為兩者的 id 不同、各自列出自己的 message，所以這是警告而非錯誤。</p><p>代價是可讀性。<strong>address 是執行期真實存在的東西，channel id 不是。</strong> 所以讀文件的人無法判斷那一個 address 實際承載哪一組 message。</p><p><a href="./decorators/channels#dynamicchannel"><code>@dynamicChannel</code></a> 不會被回報。它的 address 是 <code>null</code>，因為位址要到執行期才知道，所以兩個動態 channel 之間沒有互相說明任何事。</p><p>一對之中只回報後面那個，訊息裡會指出前面那個是誰。</p><p><strong>修法：</strong> 把兩個 operation 放進同一個 channel；或讓每個 channel 有自己的 address。</p><h3 id="channel-no-messages" tabindex="-1"><code>channel-no-messages</code> <a class="header-anchor" href="#channel-no-messages" aria-label="Permalink to &quot;`channel-no-messages`&quot;">​</a></h3><blockquote><p>Channel &#39;&lt;id&gt;&#39; has no recognizable messages. Did you forget to annotate the payload models with &#39;@message&#39;? The channel was emitted without a <code>messages</code> map.</p></blockquote><p>這個 channel 的 operation 都沒有用到帶 <code>@message</code> 的 model。channel 仍會輸出，但不輸出 <code>messages</code> 欄位。該欄位在規格中是選填，文件仍合法，但沒有 message 的 channel 通常代表 payload model 漏標 <code>@message</code>。</p><p><strong>修法：</strong> 在 payload model 上標 <code>@message</code>。同時確認這些 operation 直接寫在帶 channel 的 interface 或 namespace 裡。巢狀的 interface 是另一個範圍。</p><h3 id="duplicate-use-server" tabindex="-1"><code>duplicate-use-server</code> <a class="header-anchor" href="#duplicate-use-server" aria-label="Permalink to &quot;`duplicate-use-server`&quot;">​</a></h3><blockquote><p>@useServer names the server &#39;&lt;name&gt;&#39; more than once on this channel. AsyncAPI requires the entries of a channel&#39;s <code>servers</code> array to be unique, so one reference was emitted. Remove the extra @useServer.</p></blockquote><p>同一個 channel 上有兩個 <code>@useServer</code> 指到同一個名稱。AsyncAPI 規定該陣列的項目唯一，所以 emitter 只輸出一個參照。</p><p><strong>修法：</strong> 移除多餘的 <code>@useServer</code>。</p><h3 id="invalid-use-server-name" tabindex="-1"><code>invalid-use-server-name</code> <a class="header-anchor" href="#invalid-use-server-name" aria-label="Permalink to &quot;`invalid-use-server-name`&quot;">​</a></h3><blockquote><p>Invalid server name: &#39;&lt;name&gt;&#39;. @useServer emits a reference to the key of that server in the root <code>servers</code> map, and AsyncAPI only allows letters, digits, &#39;_&#39;, and &#39;-&#39; in such a key. A blank name is no key either. This @useServer was dropped.</p></blockquote><p><code>@useServer</code> 拿到的名稱用了 AsyncAPI 不允許出現在根層 <code>servers</code> map key 的字元。名稱按原樣檢查，與 <code>@server</code> 檢查它宣告的 key 的方式相同。空白不在允許的字元集內，所以前後帶空白的名稱兩邊都會被拒絕。emitter 不會改寫名稱，因為那會換掉作者指定的 server。</p><p><strong>修法：</strong> 名稱只使用英文字母、數字、<code>_</code> 與 <code>-</code>。</p><h3 id="undeclared-used-server" tabindex="-1"><code>undeclared-used-server</code> <a class="header-anchor" href="#undeclared-used-server" aria-label="Permalink to &quot;`undeclared-used-server`&quot;">​</a></h3><blockquote><p>@useServer names the server &#39;&lt;name&gt;&#39;, and no @server on the service namespace declares it. The emitted reference would point at nothing, and no parser could resolve it. This entry was dropped. Declare a @server with this name, or correct the name.</p></blockquote><p><code>@useServer</code> 指到的 server 名稱，在 service namespace 上沒有任何 <code>@server</code> 宣告。輸出的參照會指向文件裡不存在的 key。parser 會因為這種參照拒收整份文件，所以該筆項目被丟棄。</p><p><strong>修法：</strong> 在 service namespace 上宣告同名的 <code>@server</code>，或改正名稱。</p><h3 id="use-server-without-channel" tabindex="-1"><code>use-server-without-channel</code> <a class="header-anchor" href="#use-server-without-channel" aria-label="Permalink to &quot;`use-server-without-channel`&quot;">​</a></h3><blockquote><p>@useServer names the server &#39;&lt;name&gt;&#39;, but this interface or namespace carries neither @channel nor @dynamicChannel. Only a channel has a <code>servers</code> field, so this @useServer reaches no part of the document. Add @channel, or remove this @useServer.</p></blockquote><p><code>@useServer</code> 標在沒有 channel 的 target 上。只有 channel 才有 <code>servers</code> 欄位，所以這次套用到不了文件的任何位置。</p><p><strong>修法：</strong> 為該 target 加上 <code>@channel</code> 或 <code>@dynamicChannel</code>，或移除這個 <code>@useServer</code>。</p><h3 id="operation-without-channel" tabindex="-1"><code>operation-without-channel</code> <a class="header-anchor" href="#operation-without-channel" aria-label="Permalink to &quot;`operation-without-channel`&quot;">​</a></h3><blockquote><p>The operation &#39;&lt;name&gt;&#39; carries @send or @receive, and the interface or namespace around it carries no emitted channel. An operation always points at a channel, so this one reaches no part of the document. This operation was dropped. Add @channel or @dynamicChannel to the interface or namespace that holds it.</p></blockquote><p>operation 一定要指向一個 channel。缺少 channel 可能是因為該 target 沒有 channel decorator。也可能是宣告的 channel 被丟棄，例如在 <a href="#duplicate-channel-id"><code>duplicate-channel-id</code></a> 衝突中落敗的那一個。</p><p><strong>修法：</strong> 為包住這個 operation 的 interface 或 namespace 加上 <code>@channel</code> 或 <code>@dynamicChannel</code>。同時確認 operation 直接寫在它裡面，因為巢狀 interface 是另一個範圍。</p><h3 id="unsupported-operation-message-type" tabindex="-1"><code>unsupported-operation-message-type</code> <a class="header-anchor" href="#unsupported-operation-message-type" aria-label="Permalink to &quot;`unsupported-operation-message-type`&quot;">​</a></h3><blockquote><p>A &lt;kind&gt; cannot name the messages of an operation. This emitter does not unwrap it into messages. Write each message as its own parameter, or as a variant of a union. Mark each model with <code>@message</code>.</p></blockquote><p>operation 的參數或回傳型別寫了 <code>Tuple</code>。例如 <code>[OrderCreated, OrderShipped]</code>。那看起來像一份型別清單。它不是一份 message 清單。</p><p>emitter 不會拆開這個 tuple。拆開會變成兩個 message。簽章並沒有用額外參數或 union 成員來命名它們。該型別會從訊息清單拿掉。文件的其餘部分照樣寫出。</p><p><strong>修法：</strong> 把每個 message 寫成獨立參數，或寫成 union 的成員。每個 model 都要標 <a href="./decorators/messages#message"><code>@message</code></a>。</p><h3 id="reply-channel-not-a-channel" tabindex="-1"><code>reply-channel-not-a-channel</code> <a class="header-anchor" href="#reply-channel-not-a-channel" aria-label="Permalink to &quot;`reply-channel-not-a-channel`&quot;">​</a></h3><blockquote><p>@replyChannel names &#39;&lt;name&gt;&#39;, and that interface or namespace carries no emitted channel. A reply whose channel is unknown carries neither a checkable message list nor a checkable address, so the whole <code>reply</code> object was dropped. Add @channel or @dynamicChannel to &#39;&lt;name&gt;&#39;.</p></blockquote><p>指定的目標沒有進到文件的 channel。被丟棄的是整個 <code>reply</code> 物件，不只是 channel 欄位。只輸出一半的 reply 會表達出作者沒有寫過的內容。</p><p><strong>修法：</strong> 為指定的目標加上 <code>@channel</code> 或 <code>@dynamicChannel</code>。</p><h3 id="reply-address-needs-dynamic-channel" tabindex="-1"><code>reply-address-needs-dynamic-channel</code> <a class="header-anchor" href="#reply-address-needs-dynamic-channel" aria-label="Permalink to &quot;`reply-address-needs-dynamic-channel`&quot;">​</a></h3><blockquote><p>@replyAddress is given, and the reply channel &#39;&lt;id&gt;&#39; carries an address. AsyncAPI requires the address of that channel to be null when a reply address is given. The <code>address</code> was dropped from the reply, and the rest of the reply was kept. Declare &#39;&lt;id&gt;&#39; with @dynamicChannel instead of @channel.</p></blockquote><p>回覆位址就是回覆 channel 在執行期的位址。已經帶有 address 的 channel 會因此有兩個位址，AsyncAPI 不允許這種寫法。</p><p><strong>修法：</strong> 用 <a href="./decorators/channels#dynamicchannel"><code>@dynamicChannel</code></a> 宣告回覆 channel，或移除 <code>@replyAddress</code>。</p><h3 id="reply-without-action" tabindex="-1"><code>reply-without-action</code> <a class="header-anchor" href="#reply-without-action" aria-label="Permalink to &quot;`reply-without-action`&quot;">​</a></h3><blockquote><p>@replyChannel or @replyAddress is applied to an operation that carries neither @send nor @receive. A reply sits on an emitted operation, so this decorator reaches no part of the document. Add @send or @receive to this operation, or remove the reply decorator.</p></blockquote><p>reply 掛在輸出的 operation 上，而只有 <code>@send</code> 或 <code>@receive</code> 才會輸出 operation。</p><p><strong>修法：</strong> 為該 operation 加上 <code>@send</code> 或 <code>@receive</code>，或移除 reply 的 decorator。</p><h3 id="undeclared-server-variable" tabindex="-1"><code>undeclared-server-variable</code> <a class="header-anchor" href="#undeclared-server-variable" aria-label="Permalink to &quot;`undeclared-server-variable`&quot;">​</a></h3><blockquote><p>The template &#39;{&lt;name&gt;}&#39; in this server has no matching entry in <code>variables</code>. A reader cannot tell what to put there. The server is still emitted, with the template text unchanged. Add &#39;&lt;name&gt;&#39; to <code>variables</code>, or take the template out of <code>host</code> and <code>pathname</code>.</p></blockquote><p>server 的 <code>host</code> 或 <code>pathname</code> 含 <code>{var}</code> 模板，但同一個 server 的 <code>variables</code> 沒有對應項目。兩個欄位的模板名稱合起來視為同一組。</p><p><strong>修法：</strong> 把該名稱加進 <code>variables</code>，或從欄位中移除該模板。</p><h3 id="unused-server-variable" tabindex="-1"><code>unused-server-variable</code> <a class="header-anchor" href="#unused-server-variable" aria-label="Permalink to &quot;`unused-server-variable`&quot;">​</a></h3><blockquote><p>The variable &#39;&lt;name&gt;&#39; is declared on this server, and neither <code>host</code> nor <code>pathname</code> uses a &#39;{&lt;name&gt;}&#39; template. The variable is still emitted. Use it in one of the two fields, or remove it.</p></blockquote><p><code>variables</code> 宣告了沒有任何模板引用的項目。AsyncAPI 只會把變數代入 <code>host</code> 與 <code>pathname</code>，所以該項目不起作用。</p><p><strong>修法：</strong> 在兩個欄位其中之一使用該名稱，或刪除該項目。</p><h3 id="duplicate-server-variable-value" tabindex="-1"><code>duplicate-server-variable-value</code> <a class="header-anchor" href="#duplicate-server-variable-value" aria-label="Permalink to &quot;`duplicate-server-variable-value`&quot;">​</a></h3><blockquote><p>The <code>enum</code> of the server variable &#39;&lt;name&gt;&#39; names &#39;&lt;value&gt;&#39; more than once. AsyncAPI requires the entries to be unique, so a repeat makes the whole document fail validation. The repeat was dropped.</p></blockquote><p>server variable 的 <code>enum</code> 列出同一個值兩次。AsyncAPI 規定這些項目互不重複，重複會讓整份文件驗證失敗。</p><p>重複的項目被丟棄，該變數本身保留。若發成 error，emitter 會在寫出這份文件之前就停下來。</p><p><strong>修法：</strong> 移除重複的項目。</p><h3 id="server-variable-default-not-in-enum" tabindex="-1"><code>server-variable-default-not-in-enum</code> <a class="header-anchor" href="#server-variable-default-not-in-enum" aria-label="Permalink to &quot;`server-variable-default-not-in-enum`&quot;">​</a></h3><blockquote><p>The variable &#39;&lt;name&gt;&#39; has the default &#39;&lt;default&gt;&#39;, which is not one of its <code>enum</code> values. A client that takes the default then holds a value the same variable forbids. Both values are still emitted.</p></blockquote><p>同一個變數同時宣告 <code>default</code> 與 <code>enum</code>，而 default 不在列舉值內。AsyncAPI 不禁止這種寫法，因此兩個值都會輸出。</p><p><strong>修法：</strong> 把 default 加進 <code>enum</code>，或把 default 改成列舉內的值。</p><h3 id="blank-server-variable-value" tabindex="-1"><code>blank-server-variable-value</code> <a class="header-anchor" href="#blank-server-variable-value" aria-label="Permalink to &quot;`blank-server-variable-value`&quot;">​</a></h3><blockquote><p>The <code>\\&lt;field\\&gt;</code> of the server variable &#39;&lt;name&gt;&#39; holds an entry that is blank. A blank entry names no value, so it was dropped. A list left with no entry at all is dropped whole, and the variable is then emitted without it. Give every entry a value, or remove the ones that carry none.</p></blockquote><p>server 變數的 <code>enum</code> 或 <code>examples</code> 有項目是空字串，或只有空白字元。這種項目沒有指出任何值，所以會被丟棄。整個列表都沒有項目留下時，該欄位不會出現在變數上。</p><p><strong>修法：</strong> 給每個項目一個值，或刪除空白的項目。</p><h3 id="blank-security-scope-name" tabindex="-1"><code>blank-security-scope-name</code> <a class="header-anchor" href="#blank-security-scope-name" aria-label="Permalink to &quot;`blank-security-scope-name`&quot;">​</a></h3><blockquote><p>The <code>scopes</code> of this security scheme hold an entry that is blank. A blank entry names no scope, so it was dropped. A list left with no entry at all still reaches the document, and AsyncAPI reads it as &#39;this scheme needs no scope&#39;. Give every entry a scope name, or remove the ones that carry none.</p></blockquote><p><code>oauth2</code> 或 <code>openIdConnect</code> scheme 的 <code>scopes</code> 有項目是空字串，或只有空白字元。這種項目沒有指出任何 scope，所以會被丟棄。空的 <code>scopes</code> 仍然會寫進文件，AsyncAPI 把它讀成「這個 scheme 不需要任何 scope」。那是另一種主張。</p><p><strong>修法：</strong> 給每個項目一個 scope 名稱，或刪除空白的項目。</p><h3 id="unknown-oauth-scope" tabindex="-1"><code>unknown-oauth-scope</code> <a class="header-anchor" href="#unknown-oauth-scope" aria-label="Permalink to &quot;`unknown-oauth-scope`&quot;">​</a></h3><blockquote><p>The scope &#39;&lt;scope&gt;&#39; is not listed in <code>availableScopes</code> of any flow of this scheme. The name still reaches the document. Add it to a flow, or remove it from <code>scopes</code>.</p></blockquote><p><code>oauth2</code> scheme 的 <code>scopes</code> 列出一個名稱。沒有任何 flow 的 <code>availableScopes</code> 含有它。<code>@securityScheme</code> 的文件把 <code>scopes</code> 寫成那些對照表的子集。</p><p>該名稱仍會保留。若直接刪掉，等於改寫 <code>scopes</code>。AsyncAPI 接著會主張另一組 scope。</p><p><strong>修法：</strong> 把該名稱加進某個 flow 的 <code>availableScopes</code>，或從 <code>scopes</code> 移除。</p><h3 id="use-security-outside-server" tabindex="-1"><code>use-security-outside-server</code> <a class="header-anchor" href="#use-security-outside-server" aria-label="Permalink to &quot;`use-security-outside-server`&quot;">​</a></h3><blockquote><p>@useSecurity(&#39;&lt;schemeName&gt;&#39;) on namespace &#39;&lt;namespace&gt;&#39; was dropped. The <code>security</code> array sits on a server, and this namespace declares no @server. Move this @useSecurity to the namespace that carries @server.</p></blockquote><p><code>@useSecurity</code> 標在沒有宣告 server 的 namespace 上。emitter 把 <code>security</code> 陣列寫在 server 物件上，這次標記沒有可以落腳的位置。</p><p><strong>修法：</strong> 把 <code>@useSecurity</code> 移到標有 <code>@server</code> 的 namespace，或用 <code>@@useSecurity</code> 從目前位置 augment 過去。</p><h3 id="undeclared-security-scheme" tabindex="-1"><code>undeclared-security-scheme</code> <a class="header-anchor" href="#undeclared-security-scheme" aria-label="Permalink to &quot;`undeclared-security-scheme`&quot;">​</a></h3><blockquote><p>@useSecurity(&#39;&lt;schemeName&gt;&#39;) names a security scheme that no @securityScheme defines. The emitted reference would point at nothing, and no parser could resolve it. This entry was dropped. Declare a @securityScheme with this name, or correct the name.</p></blockquote><p><code>@useSecurity</code> 指定的名稱，程式中沒有任何 <code>@securityScheme</code> 定義。server 上的項目是指向 <code>components.securitySchemes</code> 的 <code>$ref</code>，這個 <code>$ref</code> 會指到文件中不存在的 key。</p><p><strong>修法：</strong> 新增同名的 <code>@securityScheme</code>，或修正 <code>@useSecurity</code> 的名稱。</p><h3 id="message-key-shadows-schema-key" tabindex="-1"><code>message-key-shadows-schema-key</code> <a class="header-anchor" href="#message-key-shadows-schema-key" aria-label="Permalink to &quot;`message-key-shadows-schema-key`&quot;">​</a></h3><blockquote><p>Message name &#39;&lt;name&gt;&#39; is also the components.schemas key of a different type, so a reader can misread this message as describing that type. A message key drops the namespace prefix that a schema key keeps, which makes the two overlap. Pass a different name to @message.</p></blockquote><p>文件本身仍然合法——<code>components.messages</code> 與 <code>components.schemas</code> 是兩個獨立的 map，實際上沒有撞到。風險在讀的人：<code>components.messages.Sales.Ev</code> 與 <code>components.schemas[&quot;Sales.Ev&quot;]</code> 看起來像同一個東西，描述的卻是不同型別。</p><p><strong>修法：</strong> 對 <code>@message</code> 傳入不同的名稱。</p><h3 id="sanitized-message-key" tabindex="-1"><code>sanitized-message-key</code> <a class="header-anchor" href="#sanitized-message-key" aria-label="Permalink to &quot;`sanitized-message-key`&quot;">​</a></h3><blockquote><p>Message name &#39;&lt;requested&gt;&#39; is not a legal components.messages key, so it was emitted as &#39;&lt;emitted&gt;&#39;. A key may only use the characters a-z, A-Z, 0-9, &#39;.&#39;, &#39;-&#39;, and &#39;_&#39;.</p></blockquote><p>傳給 <code>@message</code> 的名稱超出 Components Object 的合法字元集，emitter 已把違規字元編碼。因此實際輸出的 key 並不是當初要求的字串。</p><p><strong>修法：</strong> 改用只含 <code>a-z</code>、<code>A-Z</code>、<code>0-9</code>、<code>.</code>、<code>-</code>、<code>_</code> 的名稱。</p><h3 id="unknown-schema-format" tabindex="-1"><code>unknown-schema-format</code> <a class="header-anchor" href="#unknown-schema-format" aria-label="Permalink to &quot;`unknown-schema-format`&quot;">​</a></h3><blockquote><p>&#39;&lt;format&gt;&#39; is not one of the schemaFormat values AsyncAPI requires or recommends. A custom value is legal, so this one is still emitted. A custom value must not be one of the listed identifiers used with another meaning. Check the spelling, and note that every listed value carries a version, such as &#39;application/vnd.apache.avro;version=1.9.0&#39;.</p></blockquote><p>傳給 <a href="./decorators/messages#rawpayload"><code>@rawPayload</code></a> 或 <a href="./decorators/messages#rawheaders"><code>@rawHeaders</code></a> 的 <code>schemaFormat</code> 不在 AsyncAPI 列出的值裡面。該清單包含工具必須支援的值，以及規格建議的值。常見原因是漏了 <code>;version=</code> 這一段。</p><p>這個值仍然會輸出，因為規格允許自訂值。規格同時規定，自訂值不得與清單中的識別字撞名。emitter 無法檢查這條規則，因為它看不出清單中的識別字被賦予了另一種意義。所以這條規則寫在警告訊息裡。</p><p><strong>修法：</strong> 檢查拼寫；若這個值本來就是你自訂的格式，忽略這個警告。</p><h3 id="nested-header-ignored" tabindex="-1"><code>nested-header-ignored</code> <a class="header-anchor" href="#nested-header-ignored" aria-label="Permalink to &quot;`nested-header-ignored`&quot;">​</a></h3><blockquote><p>This @header marks a property that is not a top-level field of a @message model, so it stays in the payload schema. Only a top-level field is lifted into <code>headers</code>. Move the property to the message model, or describe the whole headers object with @headers.</p></blockquote><p><code>@header</code> 標到了 emitter 無法抽出的屬性：它在 payload 引用到的某個 model 裡面，而不在 message model 本身。一個 message 的 payload 是一個 object，headers 是它的同層物件。深一層的欄位沒有這種同層位置可以搬，硬抽會連帶改寫 payload 的結構。<code>@typespec/http</code> 也基於同樣理由只讀頂層的 metadata。</p><p><strong>修法：</strong> 把該屬性搬到 message model 上，或用 <code>@headers</code> 描述整個 headers 物件。</p><h3 id="inherited-header-ignored" tabindex="-1"><code>inherited-header-ignored</code> <a class="header-anchor" href="#inherited-header-ignored" aria-label="Permalink to &quot;`inherited-header-ignored`&quot;">​</a></h3><blockquote><p>This @header marks a property that &#39;&lt;message&gt;&#39; inherits through &#39;extends&#39;, so it stays in the payload schema. Only a property the message model declares itself is lifted into <code>headers</code>. Spread the base model with &#39;...&#39; instead of extending it, or describe the whole headers object with @headers.</p></blockquote><p><code>@header</code> 標到的屬性是 message 透過 <code>extends</code> 繼承來的。這種屬性在輸出的 payload 裡是頂層欄位，所以它有自己的訊息，不共用上一條。</p><p>base model 本身是獨立的宣告，每個繼承它的 model 都共用它，payload 也是用 <code>allOf</code> 引用它。從它裡面抽走一個欄位，會連帶改到其他所有使用者。展開語法 <code>...Base</code> 則是把屬性複製進 message model，那些欄位就成為 message 自己的欄位，會被抽取到 <code>headers</code>。</p><p><strong>修法：</strong> 改用 <code>...</code> 展開 base model，或用 <code>@headers</code> 描述整個 headers 物件。</p><h3 id="server-outside-service" tabindex="-1"><code>server-outside-service</code> <a class="header-anchor" href="#server-outside-service" aria-label="Permalink to &quot;`server-outside-service`&quot;">​</a></h3><blockquote><p>Server &#39;&lt;name&gt;&#39; on namespace &#39;&lt;namespace&gt;&#39; was dropped. This emitter reads the servers of the service namespace only. Move this @server to the service namespace this document is emitted from.</p></blockquote><p><code>@server</code> 標在非本文件 service namespace 的 namespace 上。emitter 只讀 service namespace 的 server，來源與 <code>info</code> 相同。</p><p><strong>修法：</strong> 把 <code>@server</code> 移到 service namespace，或用 <code>@@server</code> 從目前位置 augment 過去。</p><h3 id="multiple-services" tabindex="-1"><code>multiple-services</code> <a class="header-anchor" href="#multiple-services" aria-label="Permalink to &quot;`multiple-services`&quot;">​</a></h3><blockquote><p>Multiple services found. AsyncAPI only supports one service per document. The first one will be used.</p></blockquote><p>多個 namespace 都標了 <code>@service</code>。emitter 採用第一個，忽略其餘。</p><p><strong>修法：</strong> 一次編譯保留一個 <code>@service</code>，或把 service 拆成多次 <code>tsp compile</code>。</p><h3 id="unserializable-example" tabindex="-1"><code>unserializable-example</code> <a class="header-anchor" href="#unserializable-example" aria-label="Permalink to &quot;`unserializable-example`&quot;">​</a></h3><blockquote><p>This @example could not be serialized to JSON and was omitted from the emitted schema.</p></blockquote><p><code>@example</code> 的值含有 compiler 無法序列化成純 JSON 的內容（不支援的 scalar constructor、格式錯誤的 <code>duration.fromISO(...)</code> 等）。該 example 被丟棄，schema 本身不受影響。</p><p><strong>修法：</strong> 把 example 值簡化成 JSON 可表示的內容。</p><h3 id="inherited-header-overridden" tabindex="-1"><code>inherited-header-overridden</code> <a class="header-anchor" href="#inherited-header-overridden" aria-label="Permalink to &quot;`inherited-header-overridden`&quot;">​</a></h3><blockquote><p>The field &#39;&lt;field&gt;&#39; is lifted into the <code>headers</code> of message &#39;&lt;base&gt;&#39;. Message &#39;&lt;message&gt;&#39; extends &#39;&lt;base&gt;&#39; and describes its own headers with @headers or @rawHeaders, so the lift is cancelled and the field stays in the payload of &#39;&lt;message&gt;&#39;.</p></blockquote><p>基底 message 用 <code>@header</code> 把某個欄位抽出到它的 <code>headers</code>。衍生的 message 改用 <a href="./decorators/messages#headers"><code>@headers</code></a> 或 <a href="./decorators/messages#rawheaders"><code>@rawHeaders</code></a> 描述自己的 headers，這會整份取代原本的抽出。該欄位於是同時是基底的 header，又是衍生 message 的 payload 資料。</p><p>emitter 採用衍生 message 自己的宣告。兩種解讀都說得通，所以這個衝突會回報，而不是靜默決定。</p><p><strong>修法：</strong> 把該欄位加進衍生 message 的 headers schema；或移除那個 decorator，讓衍生 message 沿用原本的抽出。</p><h3 id="unserializable-message-example" tabindex="-1"><code>unserializable-message-example</code> <a class="header-anchor" href="#unserializable-message-example" aria-label="Permalink to &quot;`unserializable-message-example`&quot;">​</a></h3><blockquote><p>This @messageExample could not be serialized to JSON and was dropped from the emitted message.</p></blockquote><p><code>@messageExample</code> 的值含有 compiler 無法序列化為純 JSON 的內容（不支援的 scalar 建構式、格式錯誤的 <code>duration.fromISO(...)</code> 值等）。該筆整筆丟棄，連同其中本來可以序列化的欄位。只保留一半 payload 的範例會描述出應用程式從不發送的 message。</p><p><strong>修法：</strong> 把範例值改寫成可用 JSON 表示的部分。</p><h3 id="extension-target-not-emitted" tabindex="-1"><code>extension-target-not-emitted</code> <a class="header-anchor" href="#extension-target-not-emitted" aria-label="Permalink to &quot;`extension-target-not-emitted`&quot;">​</a></h3><blockquote><p>@extension sits on a target that emits no info, channel, operation, or message object, so it reaches no part of the document. Every @extension here was dropped. Move it to the service namespace, a channel, an operation, or a @message model.</p></blockquote><p><a href="./decorators/document-info#extension"><code>@extension</code></a> 接受任何 target，因為 AsyncAPI 允許每個物件帶規格擴充。這個 emitter 只寫四種物件：<code>info</code>、channel、operation 與 message。target 不產生其中任何一種時，這次套用到不了文件的任何位置。</p><p>server 與 security scheme 就是這種 target。兩者都以具名參數宣告在 namespace 上，所以一個 <code>@extension</code> 指不出它要的是哪一個。</p><p>一個 target 只回報一次，不論它帶幾個 key。錯的是位置，不是每一個 key。</p><p><strong>修法：</strong> 把這次套用移到 service namespace、<code>@channel</code> interface、<code>@send</code>／<code>@receive</code> operation，或 <code>@message</code> model 上。</p><h3 id="unserializable-extension" tabindex="-1"><code>unserializable-extension</code> <a class="header-anchor" href="#unserializable-extension" aria-label="Permalink to &quot;`unserializable-extension`&quot;">​</a></h3><blockquote><p>The value of the extension key &#39;&lt;key&gt;&#39; could not be serialized to JSON, so this @extension was dropped. Give the key a value the emitter can write.</p></blockquote><p>傳給 <a href="./decorators/document-info#extension"><code>@extension</code></a> 的值含有 compiler 無法序列化成純 JSON 的內容，例如不支援的 scalar 建構式。整次套用被丟棄。把這種值記下來，最後只會在寫檔時讓那個 key 無聲消失。</p><p>同一個 target 上其他次套用不受影響。</p><p><strong>修法：</strong> 把值簡化成 JSON 可表示的內容。</p><h3 id="unserializable-default" tabindex="-1"><code>unserializable-default</code> <a class="header-anchor" href="#unserializable-default" aria-label="Permalink to &quot;`unserializable-default`&quot;">​</a></h3><blockquote><p>This property&#39;s default value could not be serialized to JSON and was omitted from the emitted schema.</p></blockquote><p>屬性的預設值（寫法是 <code>name?: T = value</code>）含有 compiler 無法序列化成純 JSON 的內容。<code>default</code> 關鍵字被省略，schema 其餘部分不受影響。只序列化一半的預設值，等於把 schema 自己會拒絕的值寫進 schema。</p><p><strong>修法：</strong> 把預設值簡化成 JSON 可表示的內容。</p><h3 id="visibility-not-applied" tabindex="-1"><code>visibility-not-applied</code> <a class="header-anchor" href="#visibility-not-applied" aria-label="Permalink to &quot;`visibility-not-applied`&quot;">​</a></h3><blockquote><p>@visibility does not change an AsyncAPI message. A message has one shape, not a shape per lifecycle phase, so this property is emitted in full. Use @invisible to leave a property out of the document.</p></blockquote><p><a href="https://typespec.io/docs/language-basics/visibility/" target="_blank" rel="noreferrer"><code>@visibility</code></a> 讓一個 model 依生命週期階段有多種形狀。AsyncAPI message 沒有階段之分，它只有一種形狀、只送出一次。emitter 因此沒有階段可挑，會完整輸出該屬性。</p><p><code>@invisible(Lifecycle)</code> 不同。它表示該屬性不屬於任何階段，這句話不需要挑階段就能解讀，所以 emitter 會照做，把該屬性排除在外，這種情況不會回報任何訊息。</p><p><strong>修法：</strong> 要讓屬性不出現在文件裡，改用 <code>@invisible(Lifecycle)</code>；若該屬性本來就該出現在 message 裡，移除 <code>@visibility</code>。</p><h3 id="unrepresentable-numeric-constraint" tabindex="-1"><code>unrepresentable-numeric-constraint</code> <a class="header-anchor" href="#unrepresentable-numeric-constraint" aria-label="Permalink to &quot;`unrepresentable-numeric-constraint`&quot;">​</a></h3><blockquote><p>This @&lt;decorator&gt; constraint could not be represented as a JSON number (its value overflows or loses precision as a JS number) and was omitted from the emitted schema.</p></blockquote><p><code>@minValue</code> / <code>@maxValue</code> / <code>@minLength</code> 等的邊界值以 JavaScript number 表示時溢位或掉精度，例如 <code>int64</code> 上的 <code>@maxValue(9223372036854775807)</code>。該關鍵字被省略，不會輸出壞掉的值。</p><p><strong>修法：</strong> 改用 double 可精確表示的邊界值（±2^53 以內），或移除該限制。</p><h3 id="unsupported-temporal-range-constraint" tabindex="-1"><code>unsupported-temporal-range-constraint</code> <a class="header-anchor" href="#unsupported-temporal-range-constraint" aria-label="Permalink to &quot;`unsupported-temporal-range-constraint`&quot;">​</a></h3><blockquote><p>This @&lt;decorator&gt; constraint targets a date/time/duration value, which draft-07 JSON Schema cannot express as a <code>minimum</code>/<code>maximum</code>, and was omitted from the emitted schema.</p></blockquote><p><code>@minValue</code> / <code>@maxValue</code> 標在時間類 scalar（<code>utcDateTime</code>、<code>plainDate</code>、<code>duration</code> 等）上。這些 scalar 輸出為 <code>type: string</code>，draft-07 沒有能約束字串日期範圍的關鍵字。</p><p><strong>修法：</strong> 移除該限制，或改以 <code>@doc</code> 用文字描述。</p><h3 id="encoding-describes-no-variant" tabindex="-1"><code>encoding-describes-no-variant</code> <a class="header-anchor" href="#encoding-describes-no-variant" aria-label="Permalink to &quot;`encoding-describes-no-variant`&quot;">​</a></h3><blockquote><p>@encode(&quot;&lt;encoding&gt;&quot;) describes none of the variants of this union, so the encoding was left out of the emitted schema. Each variant keeps the shape its own type states.</p></blockquote><p><code>@encode</code> 標在 union 型別的屬性上，但沒有任何一個 variant 是該編碼描述的型別，例如 <code>@encode(&quot;ISO8601&quot;) d: utcDateTime | null</code>。ISO 8601 描述的是 <code>duration</code> 的傳輸格式，這兩個 variant 都不是 <code>duration</code>。編譯器接受這個 decorator，所以這是作者唯一會收到的提示。</p><p><strong>修法：</strong> 改用能對應到其中一個 variant 的編碼，或把屬性型別換成該編碼描述的型別。</p><h3 id="missing-discriminator-property" tabindex="-1"><code>missing-discriminator-property</code> <a class="header-anchor" href="#missing-discriminator-property" aria-label="Permalink to &quot;`missing-discriminator-property`&quot;">​</a></h3><blockquote><p>@discriminator(&quot;&lt;property&gt;&quot;) names a property that is not defined on this model. AsyncAPI requires the discriminating property to be defined here, so <code>discriminator</code> was omitted from the emitted schema.</p></blockquote><p><strong>修法：</strong> 在該 model 或父層上宣告這個屬性，或修正 <code>@discriminator</code> 裡的屬性名稱。指名用的是 <strong>TypeSpec</strong> 屬性名稱，不是 <code>@encodedName</code> 的 wire name。</p><h3 id="optional-discriminator-property" tabindex="-1"><code>optional-discriminator-property</code> <a class="header-anchor" href="#optional-discriminator-property" aria-label="Permalink to &quot;`optional-discriminator-property`&quot;">​</a></h3><blockquote><p>@discriminator(&quot;&lt;property&gt;&quot;) names a property that is optional on this model. AsyncAPI requires the discriminating property to be required, so <code>discriminator</code> was omitted from the emitted schema.</p></blockquote><p><strong>修法：</strong> 把 discriminating 屬性改成必填（移除 <code>?</code>）。</p><h3 id="encoded-name-override-conflict" tabindex="-1"><code>encoded-name-override-conflict</code> <a class="header-anchor" href="#encoded-name-override-conflict" aria-label="Permalink to &quot;`encoded-name-override-conflict`&quot;">​</a></h3><p>覆寫屬性的 <code>@encodedName</code> 與父層同名屬性的 wire name 不同。一般的 <code>allOf: [$ref Base, own]</code> 形狀會同時要求<strong>兩個</strong> wire name，導致任何合法 payload 都被拒絕。emitter 改為攤平該 model 的 schema（繼承屬性內嵌，不再 <code>$ref</code> 基底）。</p><p><strong>修法：</strong> 讓覆寫屬性用與父層相同的 <code>@encodedName</code>，或只在其中一層改名。</p><h3 id="never-typed-property-override" tabindex="-1"><code>never-typed-property-override</code> <a class="header-anchor" href="#never-typed-property-override" aria-label="Permalink to &quot;`never-typed-property-override`&quot;">​</a></h3><p>屬性宣告為 <code>never</code> 以移除繼承屬性，但基底的 <code>$ref</code> 分支仍會要求它。emitter 同樣改為攤平 schema（<code>never</code> 屬性省略）。</p><p><strong>修法：</strong> 若攤平可接受則不需處理，此警告只說明形狀改變。否則調整繼承結構，讓該屬性一開始就不被繼承。</p><h3 id="binding-outside-document" tabindex="-1"><code>binding-outside-document</code> <a class="header-anchor" href="#binding-outside-document" aria-label="Permalink to &quot;`binding-outside-document`&quot;">​</a></h3><blockquote><p>A &#39;&lt;protocol&gt;&#39; binding for the &lt;level&gt; level sits on a target that emits no such object, so it reaches no part of the document. This binding was dropped. Add the decorator that emits the object: @channel or @dynamicChannel for a channel, @send or @receive for an operation, @message for a message, and @server on the service namespace for a server.</p></blockquote><p>binding 依附在 target 產生的物件上。target 不產生物件時，該 binding 不會有任何效果。</p><p><code>@binding</code> 沒有指定層級，因此它回報另一段訊息。那段訊息列出四種物件，不指名單一層級。</p><p><strong>修法：</strong> 補上會產生該物件的 decorator，或移除該 binding。</p><h3 id="invalid-binding-field" tabindex="-1"><code>invalid-binding-field</code> <a class="header-anchor" href="#invalid-binding-field" aria-label="Permalink to &quot;`invalid-binding-field`&quot;">​</a></h3><blockquote><p>The &lt;protocol&gt; binding field &#39;&lt;field&gt;&#39; expects &lt;expected&gt;. The value given here is outside that, so the field was dropped and the rest of the binding was kept.</p></blockquote><p>某個欄位的值違反 binding 規格。Kafka binding 會對 <code>partitions</code>、<code>replicas</code>、<code>topicConfiguration</code>、<code>cleanup.policy</code>、<code>schemaIdLocation</code>、<code>key</code>、<code>groupId</code> 與 <code>clientId</code> 回報。JMS server binding 也會回報。回報的是沒有 <code>name</code> 與 <code>value</code> 的 <code>properties</code> 項目。</p><p><code>topicConfiguration</code> 是在序列化器無法表示對應表中某個成員時回報。帶有 <code>init</code> 的自訂 scalar 就是這種成員。該成員會讓整份對應表失敗，所以回報指的是 <code>topicConfiguration</code>，不是那個成員。</p><p>binding 的其餘部分照樣輸出。少了就寫不出 binding 的欄位代價更高，它改為回報 <a href="#invalid-required-binding-field"><code>invalid-required-binding-field</code></a>。</p><p><strong>修法：</strong> 依訊息指出的範圍填值。</p><h3 id="conflicting-message-schema-source" tabindex="-1"><code>conflicting-message-schema-source</code> <a class="header-anchor" href="#conflicting-message-schema-source" aria-label="Permalink to &quot;`conflicting-message-schema-source`&quot;">​</a></h3><blockquote><p>This message carries a payload written with @rawPayload, and the preview feature &#39;&lt;provider&gt;&#39; generated one for it too. The authored schema is the explicit statement of the two, so the document carries it and the generated one was dropped. Remove @rawPayload from this model, or turn &#39;&lt;provider&gt;&#39; off in <code>preview-features</code> in <code>tspconfig.yaml</code>.</p></blockquote><p>model 上有 <code>@rawPayload</code>，同時又有<a href="./emitter-options#預覽功能">預覽功能</a>為它產生 payload schema。</p><p>手寫的那份勝出。它是兩者中明示的一份，被產生的 schema 蓋掉會讓作者寫的內容從文件中消失。</p><p><strong>修法：</strong> 從 model 移除 <code>@rawPayload</code> 以改用產生的 schema，或從 <code>preview-features</code> 移除該功能以繼續手寫 payload。</p>',550)])])}const u=a(d,[["render",c]]);export{m as __pageData,u as default};
